    #[test]
    fn local_grant_tombstones_are_bounded_and_fail_closed_at_capacity() {
        let (snapshot, mut state) = local_grant_admission_fixture();
        state.grant_cache_max = 1;
        let first = create_grant(&state, local_grant_create(&snapshot));
        assert_eq!(first["ok"], true);
        consume_local_grant(
            &state,
            "agent:test",
            "route:test",
            "credential:test",
            7,
            &snapshot.hash,
            local_grant_create(&snapshot).request_digest.as_str(),
            local_grant_create(&snapshot).operation_digest.as_str(),
        )
        .expect("consume grant into a replay tombstone");

        let replay = create_grant(&state, local_grant_create(&snapshot));
        assert_eq!(replay["ok"], true);
        assert_eq!(replay["idempotent_replay"], true);
        assert_eq!(replay["uses_remaining"], 0);

        let mut distinct = local_grant_create(&snapshot);
        distinct.grant_id = Some("grant:distinct".to_string());
        distinct.approval_id = Some("approval:distinct".to_string());
        distinct.request_digest = sha256_prefixed(b"distinct-request");
        distinct.operation_digest = sha256_prefixed(b"distinct-operation");
        let denied = create_grant(&state, distinct);
        assert_eq!(denied["status_code"], 503);
        assert_eq!(denied["payload"]["error"], "local_grant_capacity_exhausted");
        assert_eq!(denied["payload"]["max"], 1);
        assert_eq!(state.grants.lock().expect("grant cache").len(), 1);
    }

    #[test]
    fn grant_tombstones_survive_same_signed_policy_identity_reload_only() {
        let (snapshot, state) = local_grant_admission_fixture();
        assert_eq!(
            create_grant(&state, local_grant_create(&snapshot))["ok"],
            true
        );
        consume_local_grant(
            &state,
            "agent:test",
            "route:test",
            "credential:test",
            7,
            &snapshot.hash,
            local_grant_create(&snapshot).request_digest.as_str(),
            local_grant_create(&snapshot).operation_digest.as_str(),
        )
        .expect("consume grant into a replay tombstone");

        let mut same_policy = (*snapshot).clone();
        same_policy.epoch = snapshot.epoch + 1;
        same_policy.trust_generation = snapshot.trust_generation + 1;
        same_policy.response_signing_key_id = Some("sha256:rotated-response-key".to_string());
        assert!(!clear_local_grants_if_signed_policy_changed(
            &state,
            &snapshot,
            &same_policy,
        ));
        assert_eq!(state.grants.lock().expect("grant cache").len(), 1);

        let mut changed_policy = same_policy.clone();
        changed_policy.hash = "sha256:changed-signed-policy".to_string();
        changed_policy.policy_sequence += 1;
        assert!(clear_local_grants_if_signed_policy_changed(
            &state,
            &same_policy,
            &changed_policy,
        ));
        assert!(state.grants.lock().expect("grant cache").is_empty());
    }

    #[test]
    fn grant_admission_linearizes_with_policy_reload() {
        let snapshot = test_snapshot(1);
        let state = Arc::new(test_gate_state(Arc::clone(&snapshot)));
        let (admission_entered_tx, admission_entered_rx) = mpsc::sync_channel(0);
        let (admission_release_tx, admission_release_rx) = mpsc::sync_channel(0);
        let admission_state = Arc::clone(&state);
        let admission_snapshot = Arc::clone(&snapshot);
        let admission = thread::spawn(move || {
            insert_grant_for_snapshot(
                &admission_state,
                &admission_snapshot,
                "grant-key".to_string(),
                Grant {
                    id: "grant:before-reload".to_string(),
                    approval_id: Some("approval:before-reload".to_string()),
                    max_uses: 1,
                    ttl_seconds: 30,
                    uses_remaining: 1,
                    expires_at_ms: now_epoch_ms() + 30_000,
                },
                || {
                    admission_entered_tx
                        .send(())
                        .expect("announce grant admission");
                    admission_release_rx
                        .recv()
                        .expect("release grant admission");
                },
            )
        });
        admission_entered_rx
            .recv()
            .expect("grant admission reached linearization point");

        let (reload_started_tx, reload_started_rx) = mpsc::sync_channel(0);
        let (reload_done_tx, reload_done_rx) = mpsc::sync_channel(0);
        let reload_state = Arc::clone(&state);
        let reloader = thread::spawn(move || {
            reload_started_tx.send(()).expect("announce policy reload");
            *reload_state.snapshot.write().expect("snapshot lock") = test_snapshot(2);
            reload_state.grants.lock().expect("grant cache").clear();
            reload_done_tx.send(()).expect("announce reload completion");
        });
        reload_started_rx.recv().expect("policy reload started");
        assert!(
            reload_done_rx
                .recv_timeout(Duration::from_millis(100))
                .is_err(),
            "policy replacement must not split grant admission"
        );

        admission_release_tx
            .send(())
            .expect("release grant admission");
        admission
            .join()
            .expect("grant admission thread")
            .expect("grant admitted before reload");
        reload_done_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("policy reload completed after grant admission");
        reloader.join().expect("policy reloader");
        assert_eq!(current_snapshot(&state).policy_sequence, 2);
        assert!(state.grants.lock().expect("grant cache").is_empty());

        let stale = insert_grant_for_snapshot(
            &state,
            &snapshot,
            "stale-grant-key".to_string(),
            Grant {
                id: "grant:after-reload".to_string(),
                approval_id: Some("approval:after-reload".to_string()),
                max_uses: 1,
                ttl_seconds: 30,
                uses_remaining: 1,
                expires_at_ms: now_epoch_ms() + 30_000,
            },
            || panic!("stale admission must not reach its linearization callback"),
        )
        .expect_err("stale policy grant must be rejected");
        assert_eq!(
            stale,
            GrantAdmissionError::InactivePolicy("sha256:policy-2".to_string())
        );
        assert!(state.grants.lock().expect("grant cache").is_empty());
    }

    #[test]
    fn atomic_jit_denial_uses_canonical_request_and_surfaces_pending_approval() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let address = listener.local_addr().expect("release listener address");
        let (payload_sender, payload_receiver) = mpsc::channel();
        let approval_expires_at = (OffsetDateTime::now_utc() + TimeDuration::minutes(5))
            .format(&Rfc3339)
            .expect("approval expiry");
        let server_approval_expires_at = approval_expires_at.clone();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().expect("release request");
            stream
                .set_read_timeout(Some(Duration::from_secs(2)))
                .expect("release read timeout");
            let head = read_request_head_from(&mut stream, None).expect("release request head");
            let request =
                read_request_body_from_head(&mut stream, head, MAX_MANAGEMENT_REQUEST_BODY_BYTES)
                    .expect("release request body");
            let payload = strict_json_value_from_slice(&request.body).expect("release JSON");
            let attempt_id = payload["attemptId"]
                .as_str()
                .expect("release attempt ID")
                .to_string();
            payload_sender
                .send(payload)
                .expect("capture release payload");
            let response = http_response(
                "200 OK",
                json!({
                    "apiVersion":"serverware.releaseAuthorization/v1",
                    "ok":true,
                    "authorized":false,
                    "state":"denied",
                    "reason":"jit_grant_unavailable",
                    "attemptId":attempt_id,
                    "bindingDigest":format!("sha256:{}", "a".repeat(64)),
                    "idempotentReplay":false,
                    "grantId":null,
                    "approvalRequestId":"approval:test",
                    "approvalStatus":"pending",
                    "approvalExpiresAt":server_approval_expires_at,
                    "approvalCreated":true,
                    "reservationExpiresAtEpochMs":null,
                    "dispatchStartedAtEpochMs":null,
                    "dispatchExpiresAtEpochMs":null,
                    "completionOutcome":null,
                    "retryAfterSeconds":3,
                    "quotas":[],
                    "store":{"backend":"postgres","ha":true},
                }),
            );
            stream.write_all(&response).expect("release response");
        });

        let mut snapshot_value = (*test_snapshot(1)).clone();
        snapshot_value.routes[0].jit = json!({"required":true});
        let snapshot = Arc::new(snapshot_value);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());

        let decision = decide_internal(
            &state,
            &snapshot,
            correlated_test_decision_request("A_-0123456789abcdefghijk"),
            Some("agent:test"),
        );
        server.join().expect("release server");

        assert_eq!(decision["status_code"], 428);
        assert_eq!(decision["action"], "jit_required");
        assert_eq!(decision["allowed"], false);
        assert_eq!(decision["approval_id"], "approval:test");
        assert_eq!(decision["approval_url"], "/approvals/approval:test");
        assert_eq!(decision["approval_status"], "pending");
        assert_eq!(decision["expires_at"], approval_expires_at);
        assert_eq!(decision["approval_created"], true);
        assert_eq!(decision["retry_after_seconds"], 3);
        assert_eq!(decision["payload"]["approval_id"], "approval:test");
        assert_eq!(
            decision["payload"]["approval_url"],
            "/approvals/approval:test"
        );
        assert_eq!(decision["payload"]["approval_status"], "pending");
        assert_eq!(decision["payload"]["expires_at"], approval_expires_at);
        assert_eq!(decision["payload"]["approval_created"], true);
        assert_eq!(decision["payload"]["retry_after_seconds"], 3);
        assert_eq!(
            decision["jit"]["grant_store"],
            "atomic_release_authorization"
        );
        assert_eq!(decision["jit"]["approval_id"], "approval:test");

        let payload = payload_receiver.recv().expect("reserve payload");
        let canonical = payload["canonicalRequest"].clone();
        assert_eq!(
            payload["requestDigest"],
            digest_json_ensure_ascii(&canonical)
        );
        assert_eq!(payload["operationDigest"], operation_digest(&canonical));
        assert_eq!(payload["operationContext"], canonical["operation"]);
        assert_eq!(
            canonical["request"]["headers"],
            json!({"host":"example.test"})
        );
        assert!(payload.get("redactedDisplay").is_none());
    }

    #[test]
    fn shared_jit_428_includes_approval_url_without_changing_approval_id() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("shared grant listener");
        let address = listener.local_addr().expect("shared grant address");
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().expect("shared grant request");
            let mut request = [0u8; 16 * 1024];
            let _ = stream
                .read(&mut request)
                .expect("read shared grant request");
            let body = serde_json::to_vec(&json!({
                "ok":true,
                "available":false,
                "consumed":false,
                "approval_id":"approval:shared",
                "expires_at":"2030-01-01T00:00:00Z"
            }))
            .expect("shared grant response body");
            stream
                .write_all(
                    format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                        body.len()
                    )
                    .as_bytes(),
                )
                .expect("shared grant response head");
            stream.write_all(&body).expect("shared grant response body");
        });

        let mut snapshot_value = (*test_snapshot(1)).clone();
        snapshot_value.routes[0].jit = json!({"required":true});
        let snapshot = Arc::new(snapshot_value);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.audit_url = Some("https://audit.invalid/events".to_string());
        state.audit_token = Some("audit-token".to_string());
        state.grant_consume_url = Some(format!("http://{address}/consume"));
        state.grant_consume_token = Some("grant-token".to_string());
        let decision = decide_internal(
            &state,
            &snapshot,
            correlated_test_decision_request("A_-0123456789abcdefghijk"),
            Some("agent:test"),
        );
        server.join().expect("shared grant server");

        assert_eq!(decision["status_code"], 428);
        assert_eq!(decision["approval_id"], "approval:shared");
        assert_eq!(decision["approval_url"], "/approvals/approval:shared");
    }

