    #[test]
    fn dispatch_response_loss_completes_as_unknown() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let address = listener.local_addr().expect("release listener address");
        let (payload_sender, payload_receiver) = mpsc::channel();
        let server = thread::spawn(move || {
            for _ in 0..2 {
                let (_stream, payload) = read_release_test_request(&listener);
                payload_sender.send(payload).expect("capture dispatch");
            }
            let (mut stream, payload) = read_release_test_request(&listener);
            payload_sender.send(payload).expect("capture completion");
            stream
                .write_all(&release_test_http_response(
                    "committed_indeterminate",
                    Some("unknown"),
                    true,
                    false,
                ))
                .expect("completion response");
        });

        let snapshot = test_snapshot(1);
        let mut state = test_gate_state(snapshot.clone());
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        let mut guard = ReleaseAuthorizationGuard {
            state: &state,
            reservation: ReleaseAuthorizationReservation {
                attempt_id: "attempt-test".to_string(),
                binding_digest: format!("sha256:{}", "a".repeat(64)),
                grant_id: None,
                approval_request_id: None,
                reservation_expires_at_epoch_ms: Some(1234),
                shared_quotas: Vec::new(),
                dispatch_started_at_epoch_ms: None,
                dispatch_expires_at_epoch_ms: None,
            },
            stage: ReleaseAuthorizationStage::Reserved,
        };
        guard
            .dispatch(&snapshot)
            .expect_err("lost dispatch responses must remain ambiguous");
        assert_eq!(guard.stage, ReleaseAuthorizationStage::DispatchUncertain);
        guard
            .complete("unknown")
            .expect("ambiguous dispatch must complete indeterminately");
        server.join().expect("release server");
        let payloads = payload_receiver.iter().collect::<Vec<_>>();
        assert_eq!(payloads.len(), 3);
        assert_eq!(
            payloads[0]["apiVersion"],
            "serverware.releaseAuthorizationDispatch/v1"
        );
        assert_eq!(payloads[1], payloads[0]);
        assert_eq!(payloads[2]["outcome"], "unknown");
    }

    #[test]
    fn lost_completion_response_accepts_only_explicit_terminal_replay() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let address = listener.local_addr().expect("release listener address");
        let (payload_sender, payload_receiver) = mpsc::channel();
        let server = thread::spawn(move || {
            for _ in 0..2 {
                let (_stream, payload) = read_release_test_request(&listener);
                payload_sender.send(payload).expect("capture completion");
            }
            let (mut stream, payload) = read_release_test_request(&listener);
            payload_sender
                .send(payload)
                .expect("capture replay cleanup");
            stream
                .write_all(&release_test_http_response(
                    "committed",
                    Some("forwarded"),
                    true,
                    true,
                ))
                .expect("completion replay response");
        });

        let snapshot = test_snapshot(1);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        let mut guard = ReleaseAuthorizationGuard {
            state: &state,
            reservation: ReleaseAuthorizationReservation {
                attempt_id: "attempt-test".to_string(),
                binding_digest: format!("sha256:{}", "a".repeat(64)),
                grant_id: None,
                approval_request_id: None,
                reservation_expires_at_epoch_ms: Some(1234),
                shared_quotas: Vec::new(),
                dispatch_started_at_epoch_ms: None,
                dispatch_expires_at_epoch_ms: None,
            },
            stage: ReleaseAuthorizationStage::Dispatching,
        };
        guard
            .complete_forwarded()
            .expect_err("lost forwarded completion responses must remain ambiguous");
        assert_eq!(guard.stage, ReleaseAuthorizationStage::Dispatching);
        guard
            .complete("unknown")
            .expect("unknown cleanup must accept an idempotent forwarded terminal replay");
        server.join().expect("release server");
        let payloads = payload_receiver.iter().collect::<Vec<_>>();
        assert_eq!(payloads.len(), 3);
        assert_eq!(payloads[0]["outcome"], "forwarded");
        assert_eq!(payloads[1], payloads[0]);
        assert_eq!(payloads[2]["outcome"], "unknown");
    }

    #[test]
    fn atomic_release_lifecycle_preserves_attempt_flow_correlation() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let address = listener.local_addr().expect("release listener address");
        let (payload_sender, payload_receiver) = mpsc::channel();
        let binding_digest = format!("sha256:{}", "a".repeat(64));
        let server_binding_digest = binding_digest.clone();
        let now_ms = u64::try_from(now_epoch_ms()).expect("current epoch fits u64");
        let dispatch_started_at_ms = now_ms.saturating_sub(5_000);
        let reservation_expires_at = now_ms + 30_000;
        let response_signing_key = SigningKey::from_bytes(&[91u8; 32]);
        let mut snapshot = (*test_snapshot(1)).clone();
        snapshot.response_signing_key_id = Some(test_ed25519_spki_key_id(
            &response_signing_key.verifying_key(),
        ));
        snapshot.response_verifying_key = Some(response_signing_key.verifying_key());
        snapshot.attested_response_context = Some(AttestedResponseContext {
            runtime_manifest_digest: sha256_prefixed(b"test-runtime-manifest"),
            policy_bundle_digest: snapshot.hash.clone(),
            provenance_digest: None,
            image_signatures_digest: None,
            source_tree_digest: None,
        });
        let snapshot = Arc::new(snapshot);
        let server_snapshot = Arc::clone(&snapshot);
        let server = thread::spawn(move || {
            for (state, completion_outcome) in [
                ("reserved", None),
                ("dispatching", None),
                ("committed", Some("forwarded")),
            ] {
                let (mut stream, _) = listener.accept().expect("release request");
                stream
                    .set_read_timeout(Some(Duration::from_secs(2)))
                    .expect("release read timeout");
                let head = read_request_head_from(&mut stream, None).expect("release request head");
                let request = read_request_body_from_head(
                    &mut stream,
                    head,
                    MAX_MANAGEMENT_REQUEST_BODY_BYTES,
                )
                .expect("release request body");
                payload_sender
                    .send(strict_json_value_from_slice(&request.body).expect("release JSON"))
                    .expect("capture release payload");
                let body = json!({
                    "apiVersion":"serverware.releaseAuthorization/v1",
                    "ok":true,
                    "authorized":true,
                    "state":state,
                    "reason":state,
                    "attemptId":"attempt-test",
                    "bindingDigest":server_binding_digest,
                    "idempotentReplay":false,
                    "grantId":null,
                    "approvalRequestId":null,
                    "reservationExpiresAtEpochMs":reservation_expires_at,
                    "dispatchStartedAtEpochMs":if state == "reserved" {Value::Null} else {json!(dispatch_started_at_ms)},
                    "dispatchExpiresAtEpochMs":if state == "reserved" {Value::Null} else {json!(now_ms + 10_000)},
                    "completionOutcome":completion_outcome,
                    "retryAfterSeconds":0,
                    "quotas":[],
                    "store":{"backend":"sqlite","ha":false},
                });
                let response = if state == "dispatching" {
                    let response_nonce = request
                        .headers
                        .get("x-serverware-response-nonce")
                        .expect("dispatch response nonce");
                    validate_canonical_response_nonce(response_nonce, "test dispatch")
                        .expect("canonical dispatch response nonce");
                    signed_control_plane_test_response(
                        &response_signing_key,
                        &server_snapshot,
                        &request,
                        response_nonce,
                        now_ms,
                        StatusCode::OK,
                        body,
                    )
                } else {
                    http_response("200 OK", body)
                };
                stream.write_all(&response).expect("release response");
            }
        });

        let mut state = test_gate_state(snapshot.clone());
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        let mut route = snapshot.routes[0].clone();
        route.id = "route:test".to_string();
        let operation = json!({"operation":"read"});
        let canonical = json!({
            "request":{"headers":{}},
            "operation":operation,
        });
        let request_digest = digest_json_ensure_ascii(&canonical);
        let expected_operation_digest = operation_digest(&canonical);
        let release = reserve_release_authorization(
            &state,
            "attempt-test",
            "agent:test",
            &route,
            None,
            0,
            "sha256:policy-1",
            &request_digest,
            &expected_operation_digest,
            &operation,
            &canonical,
            false,
        )
        .expect("reserve release authorization");
        let mut guard = ReleaseAuthorizationGuard {
            state: &state,
            reservation: ReleaseAuthorizationReservation {
                attempt_id: release.attempt_id,
                binding_digest: release.binding_digest,
                grant_id: release.grant_id,
                approval_request_id: release.approval_request_id,
                reservation_expires_at_epoch_ms: release.reservation_expires_at_epoch_ms,
                shared_quotas: release.validated_quotas,
                dispatch_started_at_epoch_ms: None,
                dispatch_expires_at_epoch_ms: None,
            },
            stage: ReleaseAuthorizationStage::Reserved,
        };
        let dispatch_observation = guard
            .dispatch(&snapshot)
            .expect("dispatch release authorization");
        assert_eq!(
            dispatch_observation.observed_at_epoch_ms,
            dispatch_started_at_ms
        );
        guard
            .complete_forwarded()
            .expect("complete forwarded release authorization");
        server.join().expect("release server");

        let payloads = payload_receiver.iter().collect::<Vec<_>>();
        assert_eq!(payloads.len(), 3);
        assert_eq!(payloads[0]["attemptId"], "attempt-test");
        assert_eq!(payloads[0]["flowId"], "attempt-test");
        assert_eq!(payloads[0]["requestDigest"], request_digest);
        assert_eq!(payloads[0]["operationDigest"], expected_operation_digest);
        assert_eq!(payloads[0]["canonicalRequest"], canonical);
        assert!(payloads[0].get("redactedDisplay").is_none());
        assert_eq!(payloads[1]["attemptId"], "attempt-test");
        assert_eq!(payloads[1]["bindingDigest"], binding_digest);
        assert_eq!(payloads[2]["attemptId"], "attempt-test");
        assert_eq!(payloads[2]["outcome"], "forwarded");
    }

    #[test]
    fn enrollment_session_header_is_strict_singleton_base64url() {
        for session_id in ["a".repeat(24), "Z_9-".repeat(32)] {
            let raw = format!(
                "CONNECT example.test:443 HTTP/1.1\r\nHost: example.test:443\r\nX-Serverware-Enrollment-Session: {session_id}\r\n\r\n"
            );
            let head = parse_head(raw.as_bytes()).expect("valid enrollment session header");
            assert_eq!(
                enrollment_session_id_from_headers(&head.headers)
                    .expect("validated enrollment session"),
                Some(session_id)
            );
        }

        for invalid in [
            "a".repeat(23),
            "a".repeat(129),
            format!("{}=", "a".repeat(23)),
            format!("{},b", "a".repeat(24)),
        ] {
            let raw = format!(
                "CONNECT example.test:443 HTTP/1.1\r\nHost: example.test:443\r\nX-Serverware-Enrollment-Session: {invalid}\r\n\r\n"
            );
            assert!(parse_head(raw.as_bytes())
                .err()
                .expect("malformed enrollment session must fail closed")
                .contains("24-128 base64url"));
        }

        let session_id = "a".repeat(24);
        let duplicate = format!(
            "CONNECT example.test:443 HTTP/1.1\r\nHost: example.test:443\r\nX-Serverware-Enrollment-Session: {session_id}\r\nx-serverware-enrollment-session: {session_id}\r\n\r\n"
        );
        assert!(parse_head(duplicate.as_bytes())
            .err()
            .expect("duplicate enrollment session must fail closed")
            .contains("duplicate singleton"));

        let ambiguous = BTreeMap::from([
            (
                "X-Serverware-Enrollment-Session".to_string(),
                session_id.clone(),
            ),
            ("x-serverware-enrollment-session".to_string(), session_id),
        ]);
        assert!(enrollment_session_id_from_headers(&ambiguous)
            .expect_err("case-ambiguous enrollment session must fail closed")
            .contains("ambiguous"));
    }

    #[test]
    fn connect_enrollment_session_is_inherited_but_cannot_be_overridden() {
        let session_id = "A_-0123456789abcdefghijk";
        assert_eq!(session_id.len(), 24);
        let mut inner_headers = BTreeMap::new();
        inherit_connect_enrollment_session(&mut inner_headers, Some(session_id))
            .expect("CONNECT enrollment context");
        assert_eq!(
            enrollment_session_id_from_headers(&inner_headers)
                .expect("inherited enrollment context")
                .as_deref(),
            Some(session_id)
        );

        let mut supplied_inner =
            BTreeMap::from([(ENROLLMENT_SESSION_HEADER.to_string(), "b".repeat(24))]);
        assert!(
            inherit_connect_enrollment_session(&mut supplied_inner, Some(session_id))
                .expect_err("inner request must not override CONNECT enrollment context")
                .contains("must not supply")
        );
    }

    #[test]
    fn internal_service_tokens_are_scoped_strong_and_distinct() {
        let credential_lease =
            Some("credential-lease-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-01".to_string());
        let audit = Some("audit-ingest-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-02".to_string());
        let grant = Some("grant-consume-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-03".to_string());
        let rate_limit = Some("rate-limit-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-04".to_string());
        let management = Some("rust-management-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-05".to_string());
        let names_and_tokens = [
            ("credential", &credential_lease),
            ("audit", &audit),
            ("grant", &grant),
            ("rate-limit", &rate_limit),
            ("management", &management),
        ];
        validate_internal_service_tokens(true, &names_and_tokens)
            .expect("distinct production service tokens");

        let missing = None;
        assert!(
            validate_internal_service_tokens(true, &[("missing", &missing)])
                .expect_err("missing production token")
                .contains("missing")
        );
        let weak = Some("x".repeat(32));
        assert!(validate_internal_service_tokens(true, &[("weak", &weak)])
            .expect_err("weak production token")
            .contains("high-entropy"));
        let duplicate = audit.clone();
        assert!(validate_internal_service_tokens(
            true,
            &[("audit", &audit), ("credential", &duplicate)],
        )
        .expect_err("equal production tokens")
        .contains("distinct"));
    }

