    #[test]
    fn response_constraints_are_operation_scoped_and_fail_without_context() {
        let mut route = test_snapshot(1).routes[0].clone();
        route.constraints = vec![json!({
            "id":"gmail-list-window",
            "type":"responseDateWindow",
            "phase":"response",
            "operations":["gmail.messages.list"],
            "items":["messages"],
            "dateFields":["internalDate"],
            "formats":["epochMillis"],
            "maxAgeDays":30,
            "required":true
        })];
        let detail = br#"{"id":"message-1","internalDate":"1784010000000"}"#;
        let missing = validate_response_constraints(&route, detail, None)
            .expect_err("missing response operation context must fail closed");
        assert_eq!(missing["error"], "response_operation_context_missing");
        assert!(validate_response_constraints(
            &route,
            detail,
            Some(&json!({"operation":"gmail.message.get"})),
        )
        .is_ok());

        let list = format!(
            r#"{{"messages":[{{"internalDate":"{}"}}]}}"#,
            now_epoch_ms()
        );
        assert!(validate_response_constraints(
            &route,
            list.as_bytes(),
            Some(&json!({"operation":"gmail.messages.list"})),
        )
        .is_ok());
        assert!(validate_response_constraints(
            &route,
            br#"{"messages":[]}"#,
            Some(&json!({"operation":"gmail.messages.list"})),
        )
        .is_ok());
    }

    #[test]
    fn response_bindings_match_operation_context_and_fail_closed() {
        let mut route = test_snapshot(1).routes[0].clone();
        route.constraints = vec![json!({
            "id":"stripe-payment-intent-response",
            "type":"responseBinding",
            "phase":"response",
            "successStatusCodes":[200],
            "contentTypes":["application/json"],
            "operations":["stripe.payment_intents.create"],
            "bindings":[
                {"id":"amount","operationField":"amount","responseField":"amount","comparison":"canonicalInteger"},
                {"id":"currency","operationField":"currency","responseField":"currency","comparison":"exactString"},
                {"id":"payment-method","operationField":"payment_method","responseField":"payment_method","comparison":"exactString"}
            ]
        })];
        let operation = json!({
            "operation":"stripe.payment_intents.create",
            "amount":"5000",
            "currency":"usd",
            "payment_method":"pm_12345678"
        });
        let response_decision = json!({
            "policy_hash":format!("sha256:{}", "1".repeat(64)),
            "request_digest":format!("sha256:{}", "2".repeat(64)),
            "operation_digest":format!("sha256:{}", "3".repeat(64)),
        });
        validate_response_binding_sources(&route, &operation)
            .expect("complete binding sources must be admitted before release");
        validate_response_constraints(
            &route,
            br#"{"amount":5000,"currency":"usd","payment_method":"pm_12345678"}"#,
            Some(&operation),
        )
        .expect("matching Stripe response must pass");
        let success_validation = response_binding_success_validation(
            &route,
            &response_decision,
            br#"{"amount":5000,"currency":"usd","payment_method":"pm_12345678"}"#,
            &operation,
        );
        assert_eq!(
            success_validation["bindings"].as_array().map(Vec::len),
            Some(3)
        );
        assert!(!success_validation.to_string().contains("pm_12345678"));

        let status_denied = validate_response_binding_envelope(
            &route,
            StatusCode::CREATED,
            Some("application/json"),
            &operation,
        )
        .expect_err("unlisted success status must fail closed");
        assert_eq!(status_denied["error"], "response_binding_status_denied");
        let media_denied = validate_response_binding_envelope(
            &route,
            StatusCode::OK,
            Some("text/plain"),
            &operation,
        )
        .expect_err("unlisted response media type must fail closed");
        assert_eq!(
            media_denied["error"],
            "response_binding_content_type_denied"
        );

        let root_array = validate_response_constraints(
            &route,
            br#"[{"amount":5000,"currency":"usd","payment_method":"pm_12345678"}]"#,
            Some(&operation),
        )
        .expect_err("top-level arrays must never satisfy response bindings");
        assert_eq!(root_array["error"], "response_binding_object_required");
        let split_array = validate_response_constraints(
            &route,
            br#"[{"amount":5000},{"currency":"usd"},{"payment_method":"pm_12345678"}]"#,
            Some(&operation),
        )
        .expect_err("fields split across array elements must fail closed");
        assert_eq!(split_array["error"], "response_binding_object_required");

        let mut evidence_digests = Vec::new();
        for (body, expected_binding) in [
            (
                br#"{"amount":5001,"currency":"usd","payment_method":"pm_12345678"}"#.as_slice(),
                "amount",
            ),
            (
                br#"{"amount":5000,"currency":"eur","payment_method":"pm_12345678"}"#.as_slice(),
                "currency",
            ),
            (
                br#"{"amount":5000,"currency":"usd"}"#.as_slice(),
                "payment-method",
            ),
            (
                br#"{"amount":"5000","currency":"usd","payment_method":"pm_12345678"}"#.as_slice(),
                "amount",
            ),
        ] {
            let denied = validate_response_constraints(&route, body, Some(&operation))
                .expect_err("mismatched response binding must fail closed");
            let denied = bind_response_validation_evidence(&response_decision, body, denied);
            assert_eq!(denied["binding_id"], expected_binding);
            assert_eq!(denied["status_code"], 502);
            assert!(denied["evidence_digest"]
                .as_str()
                .is_some_and(is_sha256_digest));
            evidence_digests.push(
                denied["evidence_digest"]
                    .as_str()
                    .expect("evidence digest")
                    .to_string(),
            );
            let evidence = denied.to_string();
            assert!(!evidence.contains("5001"));
            assert!(!evidence.contains("eur"));
        }
        assert_ne!(evidence_digests[0], evidence_digests[1]);
        let audit_event = decision_audit_event(
            &json!({
                "operation":operation,
                "request_digest":format!("sha256:{}", "2".repeat(64)),
                "operation_digest":format!("sha256:{}", "3".repeat(64)),
            }),
            "POST",
            &Url::parse("https://api.stripe.com/v1/payment_intents").expect("URL"),
            "blocked",
            json!({"response_validation":{"ok":false}}),
        );
        assert!(audit_event.get("operation").is_none());

        let mut missing_source = operation.clone();
        missing_source
            .as_object_mut()
            .expect("operation object")
            .remove("amount");
        let denied = validate_response_binding_sources(&route, &missing_source)
            .expect_err("missing request source must deny before credential release");
        assert_eq!(denied["error"], "response_binding_source_missing");
        assert_eq!(denied["binding_id"], "amount");

        let mut noncanonical = operation.clone();
        noncanonical["amount"] = json!("05000");
        let denied = validate_response_binding_sources(&route, &noncanonical)
            .expect_err("noncanonical integer source must deny before release");
        assert_eq!(denied["error"], "response_binding_source_invalid");
    }

    #[test]
    fn npm_publish_response_identity_and_success_fail_closed() {
        let mut route = test_snapshot(1).routes[0].clone();
        route.adapter_type = "npm.registry".to_string();
        route.constraints = vec![
            json!({
                "id":"npm-publish-identity",
                "type":"responseBinding",
                "phase":"response",
                "operations":["npm.publish"],
                "successStatusCodes":[200],
                "contentTypes":["application/json"],
                "bindings":[
                    {"id":"package-name","operationField":"packageName","responseField":"package","comparison":"exactString"},
                    {"id":"package-version","operationField":"packageVersion","responseField":"version","comparison":"exactString"}
                ]
            }),
            json!({
                "id":"npm-publish-success",
                "type":"responseJson",
                "phase":"response",
                "operations":["npm.publish"],
                "required":true,
                "fields":{"published":{"required":true,"type":"boolean","equals":true}}
            }),
        ];
        let operation = json!({
            "operation":"npm.publish",
            "packageName":"@scope/package",
            "packageVersion":"1.2.3",
            "tarballIntegrity":format!("sha512-{}", "a".repeat(86)),
        });
        validate_response_binding_sources(&route, &operation)
            .expect("complete npm publish sources must be admitted before release");
        validate_response_constraints(
            &route,
            br#"{"package":"@scope/package","version":"1.2.3","published":true}"#,
            Some(&operation),
        )
        .expect("matching npm publish response must pass");

        for (body, expected_error, expected_binding) in [
            (
                br#"{"package":"@scope/other","version":"1.2.3","published":true}"#.as_slice(),
                "response_binding_mismatch",
                Some("package-name"),
            ),
            (
                br#"{"version":"1.2.3","published":true}"#.as_slice(),
                "response_binding_field_ambiguous",
                Some("package-name"),
            ),
            (
                br#"{"package":"@scope/package","version":"9.9.9","published":true}"#.as_slice(),
                "response_binding_mismatch",
                Some("package-version"),
            ),
            (
                br#"{"package":"@scope/package","version":"1.2.3","published":false}"#.as_slice(),
                "response_json_field_equals_denied",
                None,
            ),
            (
                br#"{"package":"@scope/package","version":"1.2.3"}"#.as_slice(),
                "response_json_required_field_missing",
                None,
            ),
        ] {
            let denied = validate_response_constraints(&route, body, Some(&operation))
                .expect_err("npm publish mismatch or missing success evidence must deny");
            assert_eq!(denied["error"], expected_error);
            if let Some(binding) = expected_binding {
                assert_eq!(denied["binding_id"], binding);
            }
            assert_eq!(denied["status_code"], 502);
        }

        let mut missing_package_source = operation;
        missing_package_source
            .as_object_mut()
            .expect("operation object")
            .remove("packageName");
        let denied = validate_response_binding_sources(&route, &missing_package_source)
            .expect_err("missing npm package source must deny before credential release");
        assert_eq!(denied["error"], "response_binding_source_missing");
        assert_eq!(denied["binding_id"], "package-name");
    }

    #[test]
    fn response_content_encoding_requires_one_identity_value_or_absence() {
        let mut headers = HeaderMap::new();
        assert!(response_content_encoding_is_identity_or_absent(&headers));

        headers.append("content-encoding", HeaderValue::from_static(" identity "));
        assert!(response_content_encoding_is_identity_or_absent(&headers));

        headers.append("content-encoding", HeaderValue::from_static("gzip"));
        assert!(!response_content_encoding_is_identity_or_absent(&headers));

        let mut reordered = HeaderMap::new();
        reordered.append("content-encoding", HeaderValue::from_static("gzip"));
        reordered.append("content-encoding", HeaderValue::from_static("identity"));
        assert!(!response_content_encoding_is_identity_or_absent(&reordered));

        let mut duplicate_identity = HeaderMap::new();
        duplicate_identity.append("content-encoding", HeaderValue::from_static("identity"));
        duplicate_identity.append("content-encoding", HeaderValue::from_static("identity"));
        assert!(!response_content_encoding_is_identity_or_absent(
            &duplicate_identity
        ));

        let mut combined = HeaderMap::new();
        combined.append(
            "content-encoding",
            HeaderValue::from_static("identity, gzip"),
        );
        assert!(!response_content_encoding_is_identity_or_absent(&combined));

        let mut invalid_bytes = HeaderMap::new();
        invalid_bytes.append(
            "content-encoding",
            HeaderValue::from_bytes(&[0x80]).expect("opaque header bytes"),
        );
        assert!(!response_content_encoding_is_identity_or_absent(
            &invalid_bytes
        ));
    }

    #[test]
    fn response_proof_binds_all_consulted_raw_upstream_headers_only() {
        let mut headers = HeaderMap::new();
        headers.append("content-type", HeaderValue::from_static("application/json"));
        headers.append("content-encoding", HeaderValue::from_static("identity"));
        headers.append("content-length", HeaderValue::from_static("17"));
        headers.append("cache-control", HeaderValue::from_static("private"));
        headers.append("etag", HeaderValue::from_static("\"v1\""));
        headers.append("x-unconsulted", HeaderValue::from_static("not-bound"));
        let selected = selected_raw_policy_headers_b64(
            &json!({"allowedHeaders":["cache-control","etag"]}),
            &headers,
        );
        assert_eq!(
            selected.keys().map(String::as_str).collect::<Vec<_>>(),
            vec![
                "cache-control",
                "content-encoding",
                "content-length",
                "content-type",
                "etag",
            ]
        );
        assert_eq!(
            selected["content-type"],
            vec![general_purpose::URL_SAFE_NO_PAD.encode(b"application/json")]
        );
        assert!(!selected.contains_key("x-unconsulted"));
    }

    #[test]
    fn policy_selected_response_headers_are_credential_reflection_scanned() {
        let mut guard = ResponseSecretGuard::default();
        guard.add_text_encodings("credential-from-vault");
        let config = json!({"allowedHeaders":["etag"]});
        let mut headers = HeaderMap::new();
        headers.append(
            "etag",
            HeaderValue::from_static("\"credential-from-vault\""),
        );
        headers.append(
            "x-unconsulted",
            HeaderValue::from_static("credential-from-vault"),
        );
        assert!(selected_raw_policy_headers_detect_secret(
            &config, &headers, &guard
        ));

        headers.remove("etag");
        headers.append("etag", HeaderValue::from_static("\"safe-etag\""));
        assert!(!selected_raw_policy_headers_detect_secret(
            &config, &headers, &guard
        ));
    }

