    #[test]
    fn shared_rate_limit_request_and_key_match_server_policy() {
        let mut route = test_snapshot(1).routes[0].clone();
        route.id = "route:test".to_string();
        route.credential_ref = Some("credential:test".to_string());
        let constraint = json!({
            "id":"quota:test",
            "type":"rateLimit",
            "max":5,
            "windowSeconds":86400,
            "store":"shared",
            "key":{
                "scope":["principal","credential","credentialVersion","route","operation"],
                "operationFields":["amount","metadata.agent_request_id"]
            }
        });
        let operation = json!({
            "operation":"stripe.payment_intents.create",
            "amount":"5000",
            "metadata.agent_request_id":"req-123",
            "unbound":"still-sent-for-server-recomputation"
        });
        let key = rate_limit_key(
            &constraint,
            &route,
            "agent:test",
            Some("credential:test"),
            7,
            &operation,
        );
        assert_eq!(
            key,
            "sha256:0d09ac666d8fc0301bdf4534736845e79a5ef84d7c48eb5c9390b21d62c3eada"
        );
        let request = shared_rate_limit_request(
            &constraint,
            &route,
            "agent:test",
            Some("credential:test"),
            7,
            &format!("sha256:{}", "a".repeat(64)),
            &operation,
            true,
            &key,
            5,
            RateLimitWindow::Fixed(86400),
        );
        assert_eq!(request["operation"], "stripe.payment_intents.create");
        assert_eq!(request["operationContext"], operation);
        assert_eq!(request["counterKey"], key);
        assert_eq!(request["max"], 5);
        assert_eq!(request["windowSeconds"], 86400);
        assert!(request.get("calendarWindow").is_none());
        assert!(request.get("actorId").is_none());

        let mut calendar_constraint = constraint.clone();
        calendar_constraint
            .as_object_mut()
            .expect("calendar constraint object")
            .remove("windowSeconds");
        calendar_constraint["calendarWindow"] = json!("utcDay");
        let calendar_key = rate_limit_key(
            &calendar_constraint,
            &route,
            "agent:test",
            Some("credential:test"),
            7,
            &operation,
        );
        assert_eq!(
            calendar_key, key,
            "window kind must not split the counter key"
        );
        let calendar_request = shared_rate_limit_request(
            &calendar_constraint,
            &route,
            "agent:test",
            Some("credential:test"),
            7,
            &format!("sha256:{}", "a".repeat(64)),
            &operation,
            true,
            &calendar_key,
            5,
            RateLimitWindow::Calendar(RateLimitWindowKind::UtcDay),
        );
        assert_eq!(calendar_request["calendarWindow"], "utcDay");
        assert!(calendar_request.get("windowSeconds").is_none());

        route.constraints = vec![calendar_constraint];
        let claims = expected_shared_release_authorization_quotas(
            &route,
            "agent:test",
            Some("credential:test"),
            7,
            &operation,
        )
        .expect("calendar release quota claims");
        assert_eq!(claims.len(), 1);
        assert_eq!(claims[0].counter_key, key);
        assert_eq!(claims[0].window_kind, RateLimitWindowKind::UtcDay);
        assert_eq!(claims[0].window_seconds, None);
    }

    #[test]
    fn calendar_rate_limit_policy_admission_matches_the_shared_compiler_contract() {
        fn route_with_rate_limit(constraint: Value) -> Value {
            json!({
                "id":"route:calendar-quota",
                "principals":["agent:test"],
                "match":{
                    "scheme":"https","host":"example.test","port":443,
                    "methods":["GET"],"paths":["/resource"]
                },
                "adapter":{"type":"generic.rest","config":{
                    "request":{
                        "allowedHeaders":[],"allowedQueryKeys":[],
                        "bodyMode":"none","maxBodyBytes":0,
                        "operation":{"name":"resource.read"}
                    },
                    "response":{"mode":"json","maxBodyBytes":1024,"allowedFields":["safe"]}
                }},
                "constraints":[constraint]
            })
        }

        for calendar_window in ["utcDay", "utcIsoWeek", "utcMonth"] {
            let constraint = json!({
                "id":"quota:calendar","type":"rateLimit","max":5,
                "calendarWindow":calendar_window,"store":"shared"
            });
            validate_policy_capabilities(&policy_with_route(route_with_rate_limit(constraint)))
                .unwrap_or_else(|error| panic!("{calendar_window} must compile: {error}"));
        }
        validate_policy_capabilities(&policy_with_route(route_with_rate_limit(json!({
            "id":"quota:fixed","type":"rateLimit","max":5,
            "windowSeconds":3600,"store":"local"
        }))))
        .expect("fixed local quota remains supported");

        for (label, constraint) in [
            (
                "both",
                json!({"id":"quota:test","type":"rateLimit","max":5,"windowSeconds":60,"calendarWindow":"utcDay","store":"shared"}),
            ),
            (
                "neither",
                json!({"id":"quota:test","type":"rateLimit","max":5,"store":"shared"}),
            ),
            (
                "unknown",
                json!({"id":"quota:test","type":"rateLimit","max":5,"calendarWindow":"utcWeek","store":"shared"}),
            ),
            (
                "local",
                json!({"id":"quota:test","type":"rateLimit","max":5,"calendarWindow":"utcDay","store":"local"}),
            ),
            (
                "non-integer max",
                json!({"id":"quota:test","type":"rateLimit","max":5.5,"calendarWindow":"utcDay","store":"shared"}),
            ),
        ] {
            assert!(
                validate_policy_capabilities(&policy_with_route(route_with_rate_limit(constraint)))
                    .is_err(),
                "malformed {label} quota compiled"
            );
        }
    }

    #[test]
    fn generic_json_and_path_operation_sources_are_captured_strictly() {
        let mut route = test_snapshot(1).routes[0].clone();
        route.host = "example.test".to_string();
        route.paths = vec![compile_template("/artifacts/{artifact_id}").expect("template")];
        route.adapter_config = json!({
            "request":{
                "allowedHeaders":["content-type"],
                "allowedQueryKeys":[],
                "bodyMode":"json",
                "maxBodyBytes":4096,
                "operation":{
                    "name":"artifacts.put",
                    "jsonFields":[
                        "text","unicode_text","minimum","maximum","zero","negative_zero",
                        "metadata.id","float_value","boolean_value","object_value","array_value",
                        "null_value","too_large","missing"
                    ],
                    "pathParams":["artifact_id"]
                }
            },
            "response":{"mode":"json","maxBodyBytes":65536,"allowedFields":["id","text","size"]}
        });
        route.constraints = vec![json!({
            "id":"artifact-response",
            "type":"responseBinding",
            "phase":"response",
            "successStatusCodes":[200],
            "contentTypes":["application/json"],
            "operations":["artifacts.put"],
            "bindings":[
                {"id":"id","operationField":"artifact_id","responseField":"id","comparison":"exactString"},
                {"id":"text","operationField":"text","responseField":"text","comparison":"exactString"},
                {"id":"size","operationField":"minimum","responseField":"size","comparison":"canonicalInteger"}
            ]
        })];
        let url = Url::parse("https://example.test/artifacts/item:123").expect("URL");
        let params = route.paths[0].matches(url.path()).expect("route match");
        let route_match = RouteMatch {
            route: &route,
            params,
        };
        let body = r#"{
            "text":"hello",
            "unicode_text":"snowman \u2603",
            "minimum":-9223372036854775808,
            "maximum":9223372036854775807,
            "zero":0,
            "metadata.id":"literal-id",
            "metadata":{"id":"nested-id"},
            "float_value":1.0,
            "boolean_value":true,
            "object_value":{"nested":"value"},
            "array_value":[1],
            "null_value":null,
            "too_large":9223372036854775808
        }"#;
        let mut request = decision_request_with_body(body);
        request.url = url.to_string();
        request.headers =
            BTreeMap::from([("content-type".to_string(), "application/json".to_string())]);
        let headers = canonical_forwarded_request_headers(
            &request.headers,
            &url,
            Some(body.len() as u64),
            &Value::Null,
        )
        .expect("forwarded headers");
        let (operation, _) = validate_adapter(&request, &headers, &url, &route_match)
            .expect("valid JSON and path operation sources");
        assert_eq!(operation["operation"], "artifacts.put");
        assert_eq!(operation["artifact_id"], "item:123");
        assert_eq!(operation["text"], "hello");
        assert_eq!(operation["unicode_text"], "snowman \u{2603}");
        assert_eq!(operation["minimum"], i64::MIN.to_string());
        assert_eq!(operation["maximum"], i64::MAX.to_string());
        assert_eq!(operation["zero"], "0");
        assert_eq!(operation["metadata.id"], "literal-id");
        for omitted in [
            "negative_zero",
            "float_value",
            "boolean_value",
            "object_value",
            "array_value",
            "null_value",
            "too_large",
            "missing",
        ] {
            assert_eq!(
                operation.get(omitted),
                None,
                "unexpected capture: {omitted}"
            );
        }
        validate_response_binding_sources(&route, &operation)
            .expect("captured sources must pass preflight");
        validate_response_constraints(
            &route,
            br#"{"id":"item:123","text":"hello","size":-9223372036854775808}"#,
            Some(&operation),
        )
        .expect("matching response must satisfy JSON and path bindings");

        let mut invalid_type_route = route.clone();
        invalid_type_route.constraints[0]["bindings"][1]["operationField"] = json!("boolean_value");
        let denied = validate_response_binding_sources(&invalid_type_route, &operation)
            .expect_err("non-scalar JSON source must be absent at preflight");
        assert_eq!(denied["error"], "response_binding_source_missing");

        let mut duplicate = decision_request_with_body(r#"{"text":"first","text":"second"}"#);
        duplicate.url = url.to_string();
        duplicate.headers = request.headers;
        let denied = validate_adapter(&duplicate, &headers, &url, &route_match)
            .expect_err("duplicate JSON keys must fail consistently");
        assert_eq!(denied["error"], "request_json_invalid");

        let mut negative_zero = decision_request_with_body(r#"{"negative_zero":-0}"#);
        negative_zero.url = url.to_string();
        negative_zero.headers =
            BTreeMap::from([("content-type".to_string(), "application/json".to_string())]);
        let denied = validate_adapter(&negative_zero, &headers, &url, &route_match)
            .expect_err("integer negative zero must fail generic JSON parsing");
        assert_eq!(denied["error"], "request_json_invalid");
    }

    #[test]
    fn generic_body_sha256_operation_source_is_computed_and_bound() {
        let request_config = json!({
            "bodyMode":"json",
            "operation":{
                "name":"object_store.objects.put",
                "bodySha256Field":"requestBodySha256",
                "pathParams":["artifact_id"]
            }
        });
        let body = r#"{"content":"hello","contentType":"text/plain"}"#;
        let expected = "sha256:292df0fecc76d806319901d8e74c1f5de3cd776d05d4e4e72bdc44e83492d010";
        assert_eq!(sha256_prefixed(body.as_bytes()), expected);

        let mut request = decision_request_with_body(body);
        request.body_sha256 = Some(format!("sha256:{}", "0".repeat(64)));
        let operation = generic_operation_fields(
            &request,
            request_config.as_object().expect("request config"),
            &BTreeMap::from([("artifact_id".to_string(), "report-1".to_string())]),
        )
        .expect("computed body digest operation source");
        assert_eq!(operation["operation"], "object_store.objects.put");
        assert_eq!(operation["artifact_id"], "report-1");
        assert_eq!(operation["requestBodySha256"], expected);
        assert_ne!(
            operation["requestBodySha256"],
            request.body_sha256.clone().expect("caller digest")
        );

        let mut route = test_snapshot(1).routes[0].clone();
        route.constraints = vec![json!({
            "id":"object-store-response-binding",
            "type":"responseBinding",
            "phase":"response",
            "successStatusCodes":[200],
            "contentTypes":["application/json"],
            "operations":["object_store.objects.put"],
            "bindings":[{
                "id":"sha256",
                "operationField":"requestBodySha256",
                "responseField":"sha256",
                "comparison":"exactString"
            }]
        })];
        validate_response_binding_sources(&route, &operation)
            .expect("computed digest source must pass preflight");
        validate_response_constraints(
            &route,
            format!(r#"{{"sha256":"{expected}"}}"#).as_bytes(),
            Some(&operation),
        )
        .expect("matching computed digest must satisfy response binding");
        let denied = validate_response_constraints(
            &route,
            format!(r#"{{"sha256":"sha256:{}"}}"#, "a".repeat(64)).as_bytes(),
            Some(&operation),
        )
        .expect_err("mismatched response digest must fail closed");
        assert_eq!(denied["error"], "response_binding_mismatch");
        assert_eq!(denied["binding_id"], "sha256");
    }

    #[test]
    fn generic_form_operation_and_constraints_match_stripe_policy() {
        let mut route = test_snapshot(1).routes[0].clone();
        route.host = "api.stripe.com".to_string();
        route.paths = vec![compile_template("/v1/payment_intents").expect("template")];
        route.adapter_config = json!({
            "request":{
                "allowedHeaders":["content-type","idempotency-key"],
                "requiredHeaders":{
                    "idempotency-key":{
                        "type":"string",
                        "minLength":1,
                        "maxLength":255,
                        "pattern":"^[-A-Za-z0-9._:]{1,255}$"
                    }
                },
                "allowedQueryKeys":[],
                "bodyMode":"formUrlencoded",
                "maxBodyBytes":16384,
                "operation":{
                    "name":"stripe.payment_intents.create",
                    "bodySha256Field":"requestBodySha256",
                    "formFields":["amount","currency","payment_method","confirm","metadata.agent_request_id"]
                }
            },
            "response":{"mode":"json","maxBodyBytes":65536,"allowedFields":["id"]}
        });
        let route_match = RouteMatch {
            route: &route,
            params: BTreeMap::new(),
        };
        let constraint = json!({
            "id":"payment-intent-tokenized-only",
            "type":"formBody",
            "contentTypes":["application/x-www-form-urlencoded"],
            "allowedFields":["amount","currency","payment_method","confirm","metadata.agent_request_id","ratio","capture"],
            "requiredFields":["amount","currency","payment_method","confirm"],
            "deniedFields":["payment_method_data.card.number","source","card"],
            "fields":{
                "amount":{"type":"integer","min":50,"max":50000},
                "currency":{"type":"string","equals":"usd"},
                "payment_method":{"type":"string","pattern":"^pm_[A-Za-z0-9]{8,64}$","maxLength":67},
                "confirm":{"type":"string","equals":"true"},
                "metadata.agent_request_id":{"type":"string","maxLength":128},
                "ratio":{"type":"number","min":0.5,"max":2.0},
                "capture":{"type":"boolean","equals":true}
            }
        });
        let mut request = decision_request_with_body(
            "amount=5000&currency=usd&payment_method=pm_12345678&confirm=true&metadata%5Bagent_request_id%5D=req-123&ratio=1.5&capture=true",
        );
        request.headers = BTreeMap::from([
            (
                "Content-Type".to_string(),
                "application/x-www-form-urlencoded".to_string(),
            ),
            (
                "Idempotency-Key".to_string(),
                "agent-payment:req-123".to_string(),
            ),
        ]);
        let url = Url::parse(&request.url).expect("URL");
        let headers = canonical_forwarded_request_headers(
            &request.headers,
            &url,
            Some(request.body.len() as u64),
            &json!({"type":"bearer"}),
        )
        .expect("normalized sanitized Stripe headers");
        assert_eq!(headers["idempotency-key"], "agent-payment:req-123");
        assert_eq!(headers["host"], "api.stripe.com");
        assert_eq!(headers["content-length"], request.body.len().to_string());
        let (operation, _) = validate_adapter(&request, &headers, &url, &route_match)
            .expect("valid generic form request");
        assert_eq!(operation["operation"], "stripe.payment_intents.create");
        assert_eq!(operation["amount"], "5000");
        assert_eq!(operation["metadata.agent_request_id"], "req-123");
        assert_eq!(
            operation["requestBodySha256"],
            sha256_prefixed(request.body.as_bytes())
        );
        assert_eq!(operation.get("ratio"), None);
        enforce_form_body(&constraint, &request, &headers).expect("valid form constraint");

        let mut missing_idempotency_key = headers.clone();
        missing_idempotency_key.remove("idempotency-key");
        let missing = validate_adapter(&request, &missing_idempotency_key, &url, &route_match)
            .expect_err("missing Stripe idempotency key must be denied");
        assert_eq!(missing["error"], "required_header_missing");

        let mut invalid_idempotency_key = headers.clone();
        invalid_idempotency_key.insert(
            "idempotency-key".to_string(),
            "invalid key with spaces".to_string(),
        );
        let invalid = validate_adapter(&request, &invalid_idempotency_key, &url, &route_match)
            .expect_err("invalid Stripe idempotency key must be denied");
        assert_eq!(invalid["error"], "required_header_invalid");

        let snapshot = test_snapshot(1);
        let canonical = canonical_request(
            &request,
            &headers,
            &url,
            &snapshot.principals[0],
            &route,
            1,
            &snapshot.hash,
            &operation,
        );
        let mut changed_headers = headers.clone();
        changed_headers.insert(
            "idempotency-key".to_string(),
            "agent-payment:req-124".to_string(),
        );
        let changed = canonical_request(
            &request,
            &changed_headers,
            &url,
            &snapshot.principals[0],
            &route,
            1,
            &snapshot.hash,
            &operation,
        );
        assert_ne!(
            digest_json_ensure_ascii(&canonical),
            digest_json_ensure_ascii(&changed)
        );
        assert_ne!(operation_digest(&canonical), operation_digest(&changed));

        for (body, expected) in [
            (
                "amount=50001&currency=usd&payment_method=pm_12345678&confirm=true",
                "form_body_field_max",
            ),
            (
                "amount=50&amount=50000&currency=usd&payment_method=pm_12345678&confirm=true",
                "form_body_duplicate_field_denied",
            ),
            (
                "amount=5000&currency=usd&confirm=true&payment_method_data%5Bcard%5D%5Bnumber%5D=4242424242424242",
                "form_body_field_not_allowed",
            ),
        ] {
            let denied = enforce_form_body(
                &constraint,
                &decision_request_with_body(body),
                &headers,
            )
            .expect_err("unsafe Stripe form must be denied");
            assert_eq!(denied["error"], expected);
        }
    }

    #[test]
    fn form_parser_is_strict_and_bounded() {
        assert!(parse_form_urlencoded(&decision_request_with_body("amount=%GG")).is_err());
        let mut invalid_utf8 = decision_request_with_body("amount=replacement");
        invalid_utf8.forwarded_body_utf8_valid = Some(false);
        assert!(parse_form_urlencoded(&invalid_utf8).is_err());
        let too_many = (0..257)
            .map(|index| format!("field{index}=value"))
            .collect::<Vec<_>>()
            .join("&");
        assert!(parse_form_urlencoded(&decision_request_with_body(&too_many)).is_err());
        let parsed = parse_form_urlencoded(&decision_request_with_body(
            "metadata%5Bagent_request_id%5D=req-123",
        ))
        .expect("canonical bracket field");
        assert_eq!(
            parsed,
            vec![(
                "metadata.agent_request_id".to_string(),
                "req-123".to_string()
            )]
        );
    }

    #[test]
    fn streamed_forms_with_whole_form_constraints_fail_policy_load() {
        let mut route = generic_policy_route("formUrlencodedStream", json!(1024));
        route["constraints"] = json!([{
            "id":"form-policy",
            "type":"formBody",
            "phase":"request",
            "allowedFields":["safe"],
            "deniedFields":["secret"],
            "fields":{"safe":{"type":"string","equals":"yes"}}
        }]);
        let error = validate_policy_capabilities(&policy_with_route(route))
            .expect_err("whole-form constraints must not be admitted for streamed forms");
        assert!(error.contains("formUrlencodedStream"));
        assert!(error.contains("formBody"));
    }

    #[test]
    fn response_binding_policy_admission_is_bounded_and_captured() {
        let mut route = generic_policy_route("formUrlencoded", json!(65_536));
        route["adapter"]["config"]["request"]["operation"] = json!({
            "name":"stripe.payment_intents.create",
            "formFields":["amount","currency","payment_method"]
        });
        route["constraints"] = json!([
            {
                "id":"stripe-form",
                "type":"formBody",
                "phase":"request",
                "contentTypes":["application/x-www-form-urlencoded"],
                "allowedFields":["amount","currency","payment_method"],
                "requiredFields":["amount","currency","payment_method"],
                "fields":{
                    "amount":{"type":"integer","min":1,"max":100000},
                    "currency":{"type":"string","maxLength":3},
                    "payment_method":{"type":"string","maxLength":128}
                }
            },
            {
                "id":"stripe-response",
                "type":"responseBinding",
                "phase":"response",
                "successStatusCodes":[200],
                "contentTypes":["application/json"],
                "operations":["stripe.payment_intents.create"],
                "bindings":[
                    {"id":"amount","operationField":"amount","responseField":"amount","comparison":"canonicalInteger"},
                    {"id":"currency","operationField":"currency","responseField":"currency","comparison":"exactString"}
                ]
            }
        ]);
        validate_policy_capabilities(&policy_with_route(route.clone()))
            .expect("bounded captured response bindings must load");

        let mut uncaptured = route.clone();
        uncaptured["constraints"][1]["bindings"][0]["operationField"] = json!("uncaptured");
        let error = validate_policy_capabilities(&policy_with_route(uncaptured))
            .expect_err("uncaptured operation sources must fail admission");
        assert!(error.contains("not captured"), "{error}");

        let mut optional_source = route.clone();
        optional_source["constraints"][0]["requiredFields"] = json!(["currency", "payment_method"]);
        let error = validate_policy_capabilities(&policy_with_route(optional_source))
            .expect_err("optional binding sources must fail admission");
        assert!(error.contains("must be required by formBody"), "{error}");

        let mut mistyped_source = route.clone();
        mistyped_source["constraints"][0]["fields"]["amount"] =
            json!({"type":"string","maxLength":32});
        let error = validate_policy_capabilities(&policy_with_route(mistyped_source))
            .expect_err("mistyped binding sources must fail admission");
        assert!(error.contains("must use formBody type integer"), "{error}");

        let mut wrong_operation = route.clone();
        wrong_operation["constraints"][1]["operations"] = json!(["stripe.other"]);
        let error = validate_policy_capabilities(&policy_with_route(wrong_operation))
            .expect_err("non-applicable generic binding must fail admission");
        assert!(error.contains("does not include"), "{error}");

        let mut streaming = route;
        streaming["adapter"]["config"]["response"]["mode"] = json!("stream");
        let error = validate_policy_capabilities(&policy_with_route(streaming))
            .expect_err("response binding cannot admit streaming release");
        assert!(
            error.contains("requires a buffered JSON response"),
            "{error}"
        );
    }

    #[test]
    fn generic_operation_source_declarations_are_bounded_and_disjoint() {
        let json_path_route = || {
            let mut route = generic_policy_route("json", json!(65_536));
            route["match"]["paths"] = json!([
                "/artifacts/{artifact_id}",
                "/namespaces/{namespace}/artifacts/{artifact_id}"
            ]);
            route["adapter"]["config"]["request"]["operation"] = json!({
                "name":"artifacts.put",
                "jsonFields":["amount","label"],
                "pathParams":["artifact_id"]
            });
            route
        };

        validate_policy_capabilities(&policy_with_route(json_path_route()))
            .expect("bounded JSON and path sources must load");

        let mut body_sha256 = json_path_route();
        body_sha256["adapter"]["config"]["request"]["operation"]["bodySha256Field"] =
            json!("requestBodySha256");
        validate_policy_capabilities(&policy_with_route(body_sha256))
            .expect("computed body digest source must load for buffered JSON");

        let mut form_body_sha256 = generic_policy_route("formUrlencoded", json!(65_536));
        form_body_sha256["adapter"]["config"]["request"]["operation"] = json!({
            "name":"artifacts.put",
            "bodySha256Field":"requestBodySha256"
        });
        validate_policy_capabilities(&policy_with_route(form_body_sha256))
            .expect("computed body digest source must load for buffered form requests");

        for invalid_mode in [
            "none",
            "any",
            "stream",
            "jsonlStream",
            "jsonArrayStream",
            "jsonSseStream",
            "jsonNestedStream",
            "formUrlencodedStream",
            "csvStream",
        ] {
            let mut route = generic_policy_route(invalid_mode, json!(65_536));
            route["adapter"]["config"]["request"]["operation"] = json!({
                "name":"artifacts.put",
                "bodySha256Field":"requestBodySha256"
            });
            let error = validate_policy_capabilities(&policy_with_route(route))
                .expect_err("computed body digest requires a buffered structured body");
            assert!(
                error.contains("bodySha256Field requires buffered bodyMode"),
                "{error}"
            );
        }

        for invalid_name in [
            Value::Null,
            json!("operation"),
            json!("1digest"),
            json!("digest/value"),
            json!("a".repeat(129)),
        ] {
            let mut route = json_path_route();
            route["adapter"]["config"]["request"]["operation"]["bodySha256Field"] = invalid_name;
            let error = validate_policy_capabilities(&policy_with_route(route))
                .expect_err("invalid computed body digest field name must fail admission");
            assert!(
                error.contains("valid non-reserved operation field"),
                "{error}"
            );
        }

        for (body_mode, source_name) in [
            ("json", "jsonFields"),
            ("json", "pathParams"),
            ("formUrlencoded", "formFields"),
        ] {
            let mut route = generic_policy_route(body_mode, json!(65_536));
            route["adapter"]["config"]["request"]["operation"] = json!({
                "name":"artifacts.put",
                "bodySha256Field":"requestBodySha256",
                (source_name):["requestBodySha256"]
            });
            let error = validate_policy_capabilities(&policy_with_route(route))
                .expect_err("computed body digest field must be disjoint from request sources");
            assert!(error.contains("duplicated by bodySha256Field"), "{error}");
        }

        let mut digest_binding = generic_policy_route("json", json!(65_536));
        digest_binding["adapter"]["config"]["request"]["operation"] = json!({
            "name":"artifacts.put",
            "bodySha256Field":"requestBodySha256"
        });
        digest_binding["constraints"] = json!([{
            "id":"artifact-response",
            "type":"responseBinding",
            "phase":"response",
            "successStatusCodes":[200],
            "contentTypes":["application/json"],
            "operations":["artifacts.put"],
            "bindings":[{
                "id":"sha256",
                "operationField":"requestBodySha256",
                "responseField":"sha256",
                "comparison":"exactString"
            }]
        }]);
        validate_policy_capabilities(&policy_with_route(digest_binding.clone()))
            .expect("computed digest response binding must use exactString");
        digest_binding["constraints"][0]["bindings"][0]["comparison"] = json!("canonicalInteger");
        let error = validate_policy_capabilities(&policy_with_route(digest_binding))
            .expect_err("computed digest response binding must reject numeric comparison");
        assert!(
            error.contains("bodySha256 source") && error.contains("exactString"),
            "{error}"
        );

        for (operation, expected) in [
            (
                json!({"name":"artifacts.put","jsonFields":"amount"}),
                "must be an array",
            ),
            (
                json!({"name":"artifacts.put","jsonFields":["amount",7]}),
                "invalid or duplicate",
            ),
            (
                json!({"name":"artifacts.put","jsonFields":["amount","amount"]}),
                "invalid or duplicate",
            ),
            (
                json!({"name":"artifacts.put","jsonFields":["operation"]}),
                "invalid or duplicate",
            ),
            (
                json!({
                    "name":"artifacts.put",
                    "jsonFields":["artifact_id"],
                    "pathParams":["artifact_id"]
                }),
                "more than one source list",
            ),
            (
                json!({
                    "name":"artifacts.put",
                    "jsonFields":(0..17).map(|index| format!("field_{index}")).collect::<Vec<_>>()
                }),
                "at most 16",
            ),
        ] {
            let mut route = json_path_route();
            route["adapter"]["config"]["request"]["operation"] = operation;
            let error = validate_policy_capabilities(&policy_with_route(route))
                .expect_err("invalid generic operation sources must fail admission");
            assert!(error.contains(expected), "{error}");
        }

        let mut undeclared = json_path_route();
        undeclared["adapter"]["config"]["request"]["operation"]["pathParams"] =
            json!(["missing_id"]);
        let error = validate_policy_capabilities(&policy_with_route(undeclared))
            .expect_err("undeclared path source must fail admission");
        assert!(error.contains("not declared by path"), "{error}");

        let mut absent_from_one_path = json_path_route();
        absent_from_one_path["adapter"]["config"]["request"]["operation"]["pathParams"] =
            json!(["namespace"]);
        let error = validate_policy_capabilities(&policy_with_route(absent_from_one_path))
            .expect_err("path source absent from one matched path must fail admission");
        assert!(error.contains("not declared by path"), "{error}");

        let mut swapped_source_positions = json_path_route();
        swapped_source_positions["match"]["paths"] =
            json!(["/v1/{artifact_id}/{other}", "/v1/{other}/{artifact_id}"]);
        swapped_source_positions["adapter"]["config"]["request"]["operation"] = json!({
            "name":"artifacts.put",
            "pathParams":["artifact_id"]
        });
        let error = validate_policy_capabilities(&policy_with_route(swapped_source_positions))
            .expect_err("swapped path source positions must fail admission");
        assert!(
            error.contains("ambiguously bind operation pathParams"),
            "{error}"
        );

        let mut repeated_source = json_path_route();
        repeated_source["match"]["paths"] = json!(["/v1/{artifact_id}/{artifact_id}"]);
        repeated_source["adapter"]["config"]["request"]["operation"] = json!({
            "name":"artifacts.put",
            "pathParams":["artifact_id"]
        });
        let error = validate_policy_capabilities(&policy_with_route(repeated_source))
            .expect_err("repeated path source placeholders must fail admission");
        assert!(error.contains("repeats placeholder artifact_id"), "{error}");

        let mut stable_source_position = json_path_route();
        stable_source_position["match"]["paths"] =
            json!(["/v1/{artifact_id}/{left}", "/v1/{artifact_id}/{right}"]);
        stable_source_position["adapter"]["config"]["request"]["operation"] = json!({
            "name":"artifacts.put",
            "pathParams":["artifact_id"]
        });
        validate_policy_capabilities(&policy_with_route(stable_source_position))
            .expect("equal-specificity paths with one stable source position may load");

        let mut wrong_body_mode = json_path_route();
        wrong_body_mode["adapter"]["config"]["request"]["bodyMode"] = json!("none");
        let error = validate_policy_capabilities(&policy_with_route(wrong_body_mode))
            .expect_err("JSON operation sources require JSON body mode");
        assert!(
            error.contains("jsonFields requires bodyMode json"),
            "{error}"
        );

        let mut form_path_collision = generic_policy_route("formUrlencoded", json!(65_536));
        form_path_collision["match"]["paths"] = json!(["/artifacts/{artifact_id}"]);
        form_path_collision["adapter"]["config"]["request"]["operation"] = json!({
            "name":"artifacts.put",
            "formFields":["artifact_id"],
            "pathParams":["artifact_id"]
        });
        let error = validate_policy_capabilities(&policy_with_route(form_path_collision))
            .expect_err("form and path sources must be globally disjoint");
        assert!(error.contains("more than one source list"), "{error}");

        let mut path_only = generic_policy_route("none", json!(65_536));
        path_only["match"]["paths"] = json!(["/artifacts/{artifact_id}"]);
        path_only["adapter"]["config"]["request"]["operation"] = json!({
            "name":"artifacts.get",
            "pathParams":["artifact_id"]
        });
        validate_policy_capabilities(&policy_with_route(path_only))
            .expect("path-only operation sources must not require a request body");
    }

    #[test]
    fn response_binding_policy_proves_json_and_path_source_semantics() {
        let mut route = generic_policy_route("json", json!(65_536));
        route["match"]["paths"] = json!(["/artifacts/{artifact_id}"]);
        route["adapter"]["config"]["request"]["allowedFields"] = json!(["amount", "label"]);
        route["adapter"]["config"]["request"]["operation"] = json!({
            "name":"artifacts.put",
            "jsonFields":["amount","label"],
            "pathParams":["artifact_id"]
        });
        route["constraints"] = json!([
            {
                "id":"artifact-json",
                "type":"jsonBody",
                "phase":"request",
                "allowedFields":["amount","label"],
                "requiredFields":["amount","label"],
                "fields":{
                    "amount":{"type":"integer","min":0,"max":1048576},
                    "label":{"type":"string","maxLength":128}
                }
            },
            {
                "id":"artifact-response",
                "type":"responseBinding",
                "phase":"response",
                "successStatusCodes":[200],
                "contentTypes":["application/json"],
                "operations":["artifacts.put"],
                "bindings":[
                    {"id":"id","operationField":"artifact_id","responseField":"id","comparison":"exactString"},
                    {"id":"amount","operationField":"amount","responseField":"amount","comparison":"canonicalInteger"},
                    {"id":"label","operationField":"label","responseField":"label","comparison":"exactString"}
                ]
            }
        ]);
        validate_policy_capabilities(&policy_with_route(route.clone()))
            .expect("JSON and path response bindings must load");

        let mut optional = route.clone();
        optional["constraints"][0]["requiredFields"] = json!(["label"]);
        let error = validate_policy_capabilities(&policy_with_route(optional))
            .expect_err("optional JSON binding source must fail admission");
        assert!(error.contains("must be required by jsonBody"), "{error}");

        let mut integer_as_string = route.clone();
        integer_as_string["constraints"][0]["fields"]["amount"] =
            json!({"type":"string","maxLength":32});
        let error = validate_policy_capabilities(&policy_with_route(integer_as_string))
            .expect_err("canonical integer source requires an integer body rule");
        assert!(error.contains("must use jsonBody type integer"), "{error}");

        let mut string_as_integer = route.clone();
        string_as_integer["constraints"][0]["fields"]["label"] = json!({"type":"integer","min":0});
        let error = validate_policy_capabilities(&policy_with_route(string_as_integer))
            .expect_err("exact string source requires a string body rule");
        assert!(error.contains("must use jsonBody type string"), "{error}");

        let mut numeric_path = route;
        numeric_path["constraints"][1]["bindings"][0]["comparison"] = json!("canonicalInteger");
        let error = validate_policy_capabilities(&policy_with_route(numeric_path))
            .expect_err("path sources support exact strings only");
        assert!(error.contains("supports only exactString"), "{error}");
    }

    #[test]
    fn response_body_limit_is_typed_and_capped_at_policy_load() {
        let string_limit = policy_with_route(generic_policy_route("none", json!("1024")));
        assert!(validate_policy_capabilities(&string_limit)
            .expect_err("string response limit must be rejected")
            .contains("unsigned integer"));

        let oversized = policy_with_route(generic_policy_route(
            "none",
            json!(MAX_BUFFERED_RESPONSE_BODY_BYTES + 1),
        ));
        assert!(validate_policy_capabilities(&oversized)
            .expect_err("oversized response limit must be rejected")
            .contains("must be <="));

        let bounded = policy_with_route(generic_policy_route(
            "none",
            json!(MAX_BUFFERED_RESPONSE_BODY_BYTES),
        ));
        validate_policy_capabilities(&bounded).expect("16 MiB response limit is supported");
    }

    #[test]
    fn response_modes_are_explicit_and_fail_closed_at_policy_load() {
        for invalid_mode in [Value::String("bogus".to_string()), json!(7), Value::Null] {
            let mut route = generic_policy_route("none", json!(1024));
            route["adapter"]["config"]["response"]["mode"] = invalid_mode;
            assert!(validate_policy_capabilities(&policy_with_route(route))
                .expect_err("unsupported response mode must be rejected")
                .contains("response mode"));
        }

        let mut missing_mode = generic_policy_route("none", json!(1024));
        missing_mode["adapter"]["config"]["response"]
            .as_object_mut()
            .expect("response object")
            .remove("mode");
        assert!(
            validate_policy_capabilities(&policy_with_route(missing_mode))
                .expect_err("missing response mode must be rejected")
                .contains("response mode")
        );
    }

    #[test]
    fn credential_routes_reject_opaque_responses_and_mutating_request_streams() {
        let mut opaque_response = generic_policy_route("none", json!(1024));
        opaque_response["credentialRef"] = json!("credential:test");
        opaque_response["adapter"]["config"]["response"]["mode"] = json!("stream");
        assert!(
            validate_policy_capabilities(&policy_with_route(opaque_response))
                .expect_err("credential-bearing opaque stream must fail")
                .contains("require projection")
        );

        let mut mutating_stream = generic_policy_route("none", json!(1024));
        mutating_stream["credentialRef"] = json!("credential:test");
        mutating_stream["match"]["methods"] = json!(["POST"]);
        mutating_stream["adapter"]["config"]["request"]["bodyMode"] = json!("jsonlStream");
        mutating_stream["adapter"]["config"]["request"]["allowedFields"] = json!(["safe"]);
        assert!(
            validate_policy_capabilities(&policy_with_route(mutating_stream))
                .expect_err("credential-bearing mutating stream must fail")
                .contains("must buffer")
        );
    }

    #[test]
    fn streaming_responses_reject_released_upstream_headers() {
        let mut route = generic_policy_route("none", json!(1024));
        route["adapter"]["config"]["response"]["mode"] = json!("jsonlStream");
        route["adapter"]["config"]["response"]["allowedHeaders"] = json!(["etag"]);
        assert!(validate_policy_capabilities(&policy_with_route(route))
            .expect_err("streaming responses must not claim header release support")
            .contains("cannot release upstream headers"));
    }

    #[test]
    fn signed_npm_publish_public_registry_exception_is_exact_and_all_or_nothing() {
        let publish_route = |host: &str, constraints: Value| {
            json!({
                "id":"npm:public-exception",
                "principals":["agent:test"],
                "match":{
                    "scheme":"https","host":host,"port":443,
                    "methods":["PUT"],"paths":["/{package}"]
                },
                "credentialRef":"credential:npm",
                "adapter":{"type":"npm.registry","config":{
                    "operations":["publish"],
                    "response":{
                        "mode":"json","maxBodyBytes":65536,
                        "allowedFields":["package","version","published"],
                        "allowedHeaders":[],
                        "error":{
                            "mode":"json","maxBodyBytes":65536,
                            "allowedFields":["error","reason"],
                            "allowedHeaders":["retry-after"],
                            "onInvalid":"block"
                        }
                    }
                }},
                "constraints":constraints,
                "jit":{
                    "required":true,
                    "mode":"perOperation",
                    "ttlSeconds":30,
                    "maxUses":1,
                    "consumeOn":"forwardStart",
                    "binding":{"type":"operationDigest","fields":[
                        "principal","routeId","credentialRef","credentialVersion","policyHash",
                        "method","authority","path","query","selectedHeaders","bodySha256",
                        "packageName","packageVersion","tarballIntegrity"
                    ]},
                    "approvers":{"quorum":1,"users":["user:release"],"authn":{
                        "webauthnRequired":true,
                        "userVerification":"required",
                        "allowedAuthenticatorClasses":["hardware"],
                        "requireHardwareAttestation":true
                    }}
                }
            })
        };
        let signed_policy = |route: Value| {
            let mut policy = policy_with_route(route);
            policy["metadata"]["signature"] = json!("ed25519:test-signature");
            policy
        };
        let operation_constraint = json!({
            "id":"npm-publish-only",
            "type":"operationPolicy",
            "allowedOperations":["npm.publish"]
        });

        validate_policy_capabilities(&signed_policy(publish_route(
            "registry.npmjs.org",
            json!([operation_constraint.clone()]),
        )))
        .expect("exact public npm host may omit both response assertions");

        let non_public_error = validate_policy_capabilities(&signed_policy(publish_route(
            "registry.example.test",
            json!([operation_constraint.clone()]),
        )))
        .expect_err("compatible non-public registry must provide both response assertions");
        assert_eq!(
            non_public_error,
            "route npm:public-exception signed npm.publish requires a responseBinding scoped only to npm.publish"
        );

        let partial_public_error = validate_policy_capabilities(&signed_policy(publish_route(
            "registry.npmjs.org",
            json!([
                operation_constraint,
                {
                    "id":"npm-publish-success",
                    "type":"responseJson",
                    "phase":"response",
                    "operations":["npm.publish"],
                    "required":true,
                    "fields":{"published":{"required":true,"type":"boolean","equals":true}}
                }
            ]),
        )))
        .expect_err("partial public npm response assertion must fail closed");
        assert_eq!(
            partial_public_error,
            "route npm:public-exception signed npm.publish requires a responseBinding scoped only to npm.publish"
        );
    }

    #[test]
    fn high_risk_adapter_invariants_are_policy_load_requirements() {
        let gmail_route = json!({
            "id":"gmail:test",
            "principals":["agent:test"],
            "match":{
                "scheme":"https","host":"gmail.googleapis.com","port":443,
                "methods":["GET"],"paths":["/gmail/v1/users/{user}/messages"]
            },
            "credentialRef":"credential:gmail",
            "adapter":{"type":"gmail.v1","config":{
                "maxAgeDays":30,
                "maxResults":25,
                "forceQuery":true,
                "allowMessageGetOnlyFromPriorSearch":true,
                "cacheTtlSeconds":300,
                "response":{
                    "validateInternalDate":true,
                    "validateListByMetadataFetch":true,
                    "metadataFetch":{
                        "maxMessages":10,
                        "perRequestTimeoutMs":1500,
                        "totalTimeoutMs":8000,
                        "maxBodyBytes":4096
                    },
                    "maxBodyBytes":1048576,
                    "allowedFields":["id","internalDate","payload.headers"],
                    "allowedHeaders":[],
                    "allowedMessageHeaderNames":["From","Subject"],
                    "error":{
                        "mode":"json",
                        "maxBodyBytes":65536,
                        "allowedFields":["error.code","error.message"],
                        "allowedHeaders":["retry-after"],
                        "onInvalid":"block"
                    },
                    "onViolation":"block"
                }
            }}
        });
        validate_policy_capabilities(&policy_with_route(gmail_route.clone()))
            .expect("fully bounded Gmail policy");
        let mut unsafe_gmail = gmail_route.clone();
        unsafe_gmail["adapter"]["config"]["forceQuery"] = json!(false);
        assert!(
            validate_policy_capabilities(&policy_with_route(unsafe_gmail))
                .expect_err("Gmail without query forcing must fail policy load")
                .contains("forceQuery")
        );
        for (field, value, expected) in [
            ("maxMessages", json!(33), "between 1 and 32"),
            ("perRequestTimeoutMs", json!(3001), "between 1 and 3000"),
            ("totalTimeoutMs", json!(10001), "between 1 and 10000"),
            ("maxBodyBytes", json!(8193), "between 1 and 8192"),
        ] {
            let mut unsafe_gmail = gmail_route.clone();
            unsafe_gmail["adapter"]["config"]["response"]["metadataFetch"][field] = value;
            let error = validate_policy_capabilities(&policy_with_route(unsafe_gmail))
                .expect_err("out-of-range Gmail metadata fanout policy must fail closed");
            assert!(error.contains(expected), "{field}: {error}");
        }
        let mut inverted_timeouts = gmail_route.clone();
        inverted_timeouts["adapter"]["config"]["response"]["metadataFetch"]
            ["perRequestTimeoutMs"] = json!(2000);
        inverted_timeouts["adapter"]["config"]["response"]["metadataFetch"]["totalTimeoutMs"] =
            json!(1000);
        assert!(
            validate_policy_capabilities(&policy_with_route(inverted_timeouts))
                .expect_err("per-request metadata timeout cannot exceed the total timeout")
                .contains("perRequestTimeoutMs cannot exceed totalTimeoutMs")
        );
        let mut too_many = gmail_route.clone();
        too_many["adapter"]["config"]["maxResults"] = json!(5);
        assert!(validate_policy_capabilities(&policy_with_route(too_many))
            .expect_err("metadata maxMessages cannot exceed maxResults")
            .contains("cannot exceed maxResults"));
        let mut missing_id = gmail_route;
        missing_id["adapter"]["config"]["response"]["allowedFields"] = json!(["internalDate"]);
        assert!(validate_policy_capabilities(&policy_with_route(missing_id))
            .expect_err("hydrated Gmail responses must release message IDs")
            .contains("requires id"));

        let npm_route = json!({
            "id":"npm:test",
            "principals":["agent:test"],
            "match":{
                "scheme":"https","host":"registry.npmjs.org","port":443,
                "methods":["PUT"],"paths":["/{package}"]
            },
            "credentialRef":"credential:npm",
            "adapter":{"type":"npm.registry","config":{
                "operations":["publish"],
                "response":{
                    "mode":"json",
                    "maxBodyBytes":65536,
                    "allowedFields":["package","version","published"],
                    "allowedHeaders":[],
                    "error":{
                        "mode":"json",
                        "maxBodyBytes":65536,
                        "allowedFields":["error","reason"],
                        "allowedHeaders":["retry-after"],
                        "onInvalid":"block"
                    }
                }
            }},
            "constraints":[
                {
                    "id":"npm-publish-package-binding",
                    "type":"responseBinding",
                    "phase":"response",
                    "operations":["npm.publish"],
                    "successStatusCodes":[200,201],
                    "contentTypes":["application/json"],
                    "bindings":[
                        {
                            "id":"package-name",
                            "operationField":"packageName",
                            "responseField":"package",
                            "comparison":"exactString"
                        },
                        {
                            "id":"package-version",
                            "operationField":"packageVersion",
                            "responseField":"version",
                            "comparison":"exactString"
                        }
                    ]
                },
                {
                    "id":"npm-publish-success",
                    "type":"responseJson",
                    "phase":"response",
                    "operations":["npm.publish"],
                    "required":true,
                    "fields":{"published":{"required":true,"type":"boolean","equals":true}}
                }
            ],
            "jit":{
                "required":true,
                "mode":"perOperation",
                "ttlSeconds":30,
                "maxUses":1,
                "consumeOn":"forwardStart",
                "binding":{"type":"operationDigest","fields":[
                    "principal","routeId","credentialRef","credentialVersion","policyHash",
                    "method","authority","path","query","selectedHeaders","bodySha256",
                    "packageName","packageVersion","tarballIntegrity"
                ]},
                "approvers":{"quorum":1,"users":["user:release"],"authn":{
                    "webauthnRequired":true,
                    "userVerification":"required",
                    "allowedAuthenticatorClasses":["hardware"],
                    "requireHardwareAttestation":true
                }}
            }
        });
        let signed_npm_policy = |route: Value| {
            let mut policy = policy_with_route(route);
            policy["metadata"]["signature"] = json!("ed25519:test-signature");
            policy
        };
        validate_policy_capabilities(&signed_npm_policy(npm_route.clone()))
            .expect("hardware-bound npm policy");

        let mut missing_response_binding = npm_route.clone();
        missing_response_binding["constraints"]
            .as_array_mut()
            .expect("npm constraints")
            .retain(|constraint| {
                constraint.get("type").and_then(Value::as_str) != Some("responseBinding")
            });
        assert_eq!(
            validate_policy_capabilities(&signed_npm_policy(missing_response_binding))
                .expect_err("signed npm publish without responseBinding must fail policy load"),
            "route npm:test signed npm.publish requires a responseBinding scoped only to npm.publish"
        );

        let mut missing_response_json = npm_route.clone();
        missing_response_json["constraints"]
            .as_array_mut()
            .expect("npm constraints")
            .retain(|constraint| {
                constraint.get("type").and_then(Value::as_str) != Some("responseJson")
            });
        assert_eq!(
            validate_policy_capabilities(&signed_npm_policy(missing_response_json))
                .expect_err("signed npm publish without responseJson must fail policy load"),
            "route npm:test signed npm.publish requires a responseJson success constraint scoped only to npm.publish"
        );

        let mut mismatched_success = npm_route.clone();
        mismatched_success["constraints"][1]["fields"]["published"]["equals"] = json!(false);
        assert_eq!(
            validate_policy_capabilities(&signed_npm_policy(mismatched_success))
                .expect_err("signed npm publish with false success assertion must fail policy load"),
            "route npm:test signed npm.publish responseJson success constraint must require published to equal true"
        );

        let mut missing_package_binding = npm_route.clone();
        missing_package_binding["constraints"][0]["bindings"]
            .as_array_mut()
            .expect("npm response bindings")
            .retain(|binding| {
                binding.get("operationField").and_then(Value::as_str) != Some("packageVersion")
            });
        assert_eq!(
            validate_policy_capabilities(&signed_npm_policy(missing_package_binding))
                .expect_err("npm publish response binding without packageVersion must fail policy load"),
            "route npm:test responseBinding npm-publish-package-binding must bind npm.publish packageName and packageVersion"
        );

        let mut mismatched_operation = npm_route.clone();
        mismatched_operation["constraints"][0]["operations"] = json!(["npm.distTagWrite"]);
        assert_eq!(
            validate_policy_capabilities(&signed_npm_policy(mismatched_operation))
                .expect_err("npm publish response binding with mismatched operation must fail policy load"),
            "route npm:test responseBinding npm-publish-package-binding must be scoped only to configured npm.publish"
        );

        let mut invalid_success_status = npm_route.clone();
        invalid_success_status["constraints"][0]["successStatusCodes"] = json!([202]);
        assert_eq!(
            validate_policy_capabilities(&signed_npm_policy(invalid_success_status))
                .expect_err("npm publish response binding with status 202 must fail policy load"),
            "route npm:test responseBinding npm-publish-package-binding npm.publish successStatusCodes may contain only 200 or 201"
        );

        let mut invalid_success_content_type = npm_route.clone();
        invalid_success_content_type["constraints"][0]["contentTypes"] =
            json!(["application/problem+json"]);
        assert_eq!(
            validate_policy_capabilities(&signed_npm_policy(invalid_success_content_type))
                .expect_err("npm publish response binding with non-npm JSON type must fail policy load"),
            "route npm:test responseBinding npm-publish-package-binding npm.publish contentTypes must be exactly application/json"
        );

        let mut oversized_response = npm_route.clone();
        oversized_response["adapter"]["config"]["response"]["maxBodyBytes"] = json!(65_537);
        assert_eq!(
            validate_policy_capabilities(&signed_npm_policy(oversized_response))
                .expect_err("signed npm publish response over 64 KiB must fail policy load"),
            "route npm:test responseBinding requires a buffered JSON response capped at 65536 bytes"
        );

        let mut unsafe_npm = npm_route;
        unsafe_npm["jit"]["approvers"]["authn"]["requireHardwareAttestation"] = json!(false);
        assert!(validate_policy_capabilities(&signed_npm_policy(unsafe_npm))
            .expect_err("npm write without hardware attestation must fail policy load")
            .contains("hardware-attested"));

        let x_read_route = json!({
            "id":"x:read",
            "principals":["agent:test"],
            "match":{
                "scheme":"https","host":"api.x.com","port":443,
                "methods":["GET"],"paths":["/2/**"]
            },
            "credentialRef":"credential:x",
            "adapter":{"type":"x.v2","config":{
                "mode":"readOnly",
                "blockWrites":true,
                "appIds":["approved-app"],
                "allowedReadOperations":["tweets.read","users.read"],
                "response":{"mode":"json","maxBodyBytes":1048576,"allowedFields":["data","meta"]}
            }},
            "constraints":[{
                "id":"x-read-operations",
                "type":"operationPolicy",
                "allowedOperations":["tweets.read","users.read"]
            }]
        });
        validate_policy_capabilities(&policy_with_route(x_read_route.clone()))
            .expect("explicit bounded X reads");
        let mut unsafe_x_read = x_read_route;
        unsafe_x_read["match"]["methods"] = json!(["GET", "POST"]);
        assert!(
            validate_policy_capabilities(&policy_with_route(unsafe_x_read))
                .expect_err("X read route with a write method must fail policy load")
                .contains("only match GET")
        );

        let x_write_route = json!({
            "id":"x:write",
            "principals":["agent:test"],
            "match":{
                "scheme":"https","host":"api.x.com","port":443,
                "methods":["POST"],"paths":["/2/tweets"]
            },
            "credentialRef":"credential:x",
            "adapter":{"type":"x.v2","config":{
                "mode":"controlledWrite",
                "blockWrites":false,
                "appIds":["approved-app"],
                "response":{"mode":"json","maxBodyBytes":65536,"allowedFields":["data"]}
            }},
            "constraints":[
                {"id":"x-write-operation","type":"operationPolicy","allowedOperations":["tweets.write"]},
                {"id":"x-write-body","type":"jsonBody","allowedFields":["text"],"requiredFields":["text"]}
            ]
        });
        validate_policy_capabilities(&policy_with_route(x_write_route.clone()))
            .expect("explicit X post write");
        let mut unprojected_x_write = x_write_route.clone();
        unprojected_x_write["adapter"]["config"]["response"]
            .as_object_mut()
            .expect("X write response")
            .remove("allowedFields");
        assert!(
            validate_policy_capabilities(&policy_with_route(unprojected_x_write))
                .expect_err("X write JSON responses must define a projection")
                .contains("allowedFields must be a non-empty array")
        );
        let mut unsafe_x_write = x_write_route;
        unsafe_x_write["match"]["paths"] = json!(["/2/**"]);
        assert!(
            validate_policy_capabilities(&policy_with_route(unsafe_x_write))
                .expect_err("broad X write route must fail policy load")
                .contains("only POST /2/tweets")
        );
    }

    #[test]
    fn body_constraints_require_an_explicit_unknown_field_allowlist() {
        let mut route = generic_policy_route("json", json!(1024));
        route["constraints"] = json!([{
            "id":"body:test",
            "type":"jsonBody",
            "requiredFields":["safe"],
            "fields":{"safe":{"type":"string"}}
        }]);
        let error = validate_policy_capabilities(&policy_with_route(route))
            .expect_err("body policy without allowedFields must fail policy load");
        assert!(error.contains("allowedFields"));
        assert!(error.contains("fail closed"));
    }

    #[test]
    fn json_body_allowed_fields_reject_unknown_empty_containers() {
        let constraint = json!({
            "id":"container-fields",
            "type":"jsonBody",
            "contentTypes":["application/json"],
            "allowedFields":["safe","metadata","tags"],
            "fields":{
                "metadata":{"type":"object"},
                "tags":{"type":"array","minItems":1,"maxItems":2}
            }
        });
        let headers =
            BTreeMap::from([("content-type".to_string(), "application/json".to_string())]);

        for (body, field) in [
            (r#"{"safe":"ok","unknown":{}}"#, "unknown"),
            (r#"{"safe":"ok","unknown":[]}"#, "unknown"),
            (
                r#"{"safe":"ok","unknown":{"nested":[{},[]]}}"#,
                "unknown.nested",
            ),
        ] {
            let denied =
                enforce_json_body(&constraint, &decision_request_with_body(body), &headers)
                    .expect_err("unknown empty containers must fail closed");
            assert_eq!(denied["error"], "json_body_field_not_allowed");
            assert_eq!(denied["field"], field);
        }

        enforce_json_body(
            &constraint,
            &decision_request_with_body(
                r#"{"safe":"ok","metadata":{"nested":{"empty":[]}},"tags":[{},[]]}"#,
            ),
            &headers,
        )
        .expect("explicitly allowlisted container paths must remain usable");

        let mut permits_empty_array = constraint.clone();
        permits_empty_array["fields"]["tags"]["minItems"] = json!(0);
        enforce_json_body(
            &permits_empty_array,
            &decision_request_with_body(r#"{"safe":"ok","metadata":{},"tags":[]}"#),
            &headers,
        )
        .expect("an allowlisted empty array must pass when its bounds permit it");

        for (body, error) in [
            (
                r#"{"safe":"ok","metadata":{},"tags":{}}"#,
                "json_body_field_type_denied",
            ),
            (
                r#"{"safe":"ok","metadata":{},"tags":[]}"#,
                "json_body_field_min_items",
            ),
            (
                r#"{"safe":"ok","metadata":{},"tags":[{},{},{}]}"#,
                "json_body_field_max_items",
            ),
        ] {
            let denied =
                enforce_json_body(&constraint, &decision_request_with_body(body), &headers)
                    .expect_err("container field rules must still be enforced");
            assert_eq!(denied["error"], error);
            assert_eq!(denied["field"], "tags");
        }
    }

    #[test]
    fn field_rule_type_compatibility_is_consistent_across_constraint_runtimes() {
        let policy_for_rule = |constraint_type: &str, body_mode: &str, rule: Value| {
            let constraint = if constraint_type == "responseJson" {
                json!({
                    "id":"typed-field",
                    "type":"responseJson",
                    "phase":"response",
                    "fields":{"value":rule}
                })
            } else {
                json!({
                    "id":"typed-field",
                    "type":constraint_type,
                    "allowedFields":["value"],
                    "fields":{"value":rule}
                })
            };
            let mut route = generic_policy_route(body_mode, json!(1024));
            route["constraints"] = json!([constraint]);
            policy_with_route(route)
        };
        let constraint_types = [
            ("jsonBody", "json"),
            ("formBody", "formUrlencoded"),
            ("responseJson", "none"),
        ];
        let incompatible_rules = [
            ("numeric rule without type", json!({"min":0})),
            (
                "numeric rule with string type",
                json!({"type":"string","max":10}),
            ),
            ("string rule without type", json!({"minLength":1})),
            (
                "string rule with numeric type",
                json!({"type":"number","maxLength":8}),
            ),
            (
                "pattern with numeric type",
                json!({"type":"number","maxLength":8,"pattern":"^[0-9]{1,8}$"}),
            ),
            ("array rule without type", json!({"minItems":1})),
            (
                "array rule with object type",
                json!({"type":"object","maxItems":2}),
            ),
        ];

        for (constraint_type, body_mode) in constraint_types {
            for (label, rule) in &incompatible_rules {
                let error = validate_policy_capabilities(&policy_for_rule(
                    constraint_type,
                    body_mode,
                    rule.clone(),
                ))
                .expect_err("type-incompatible field rules must fail policy admission");
                assert!(error.contains(constraint_type), "{label}: {error}");
                assert!(error.contains("require"), "{label}: {error}");
            }

            for rule in [
                json!({"type":"number","min":0,"max":10}),
                json!({"type":"integer","min":0,"max":10}),
                json!({"type":"string","minLength":1,"maxLength":8}),
                json!({"type":"array","minItems":1,"maxItems":2}),
            ] {
                validate_policy_capabilities(&policy_for_rule(constraint_type, body_mode, rule))
                    .expect("compatible field rules must remain admissible");
            }
        }
    }

    #[test]
    fn json_body_enforces_bounded_field_patterns() {
        let constraint = json!({
            "id":"payment-method",
            "type":"jsonBody",
            "contentTypes":["application/json"],
            "allowedFields":["payment_method"],
            "requiredFields":["payment_method"],
            "fields":{
                "payment_method":{
                    "type":"string",
                    "pattern":"^pm_[A-Za-z0-9]{8,64}$",
                    "maxLength":67
                }
            }
        });
        let headers =
            BTreeMap::from([("content-type".to_string(), "application/json".to_string())]);
        enforce_json_body(
            &constraint,
            &decision_request_with_body(r#"{"payment_method":"pm_12345678"}"#),
            &headers,
        )
        .expect("matching bounded JSON pattern");
        let denied = enforce_json_body(
            &constraint,
            &decision_request_with_body(r#"{"payment_method":"card_12345678"}"#),
            &headers,
        )
        .expect_err("non-matching JSON pattern must fail closed");
        assert_eq!(denied["error"], "json_body_field_pattern_denied");
        assert_eq!(denied["field"], "payment_method");
    }

    #[test]
    fn body_patterns_must_use_the_bounded_runtime_grammar() {
        for (constraint_type, body_mode) in [("jsonBody", "json"), ("formBody", "formUrlencoded")] {
            let mut route = generic_policy_route(body_mode, json!(1024));
            route["constraints"] = json!([{
                "id":"pattern-policy",
                "type":constraint_type,
                "allowedFields":["safe"],
                "fields":{"safe":{
                    "type":"string",
                    "pattern":"^safe[0-9]+$",
                    "maxLength":64
                }}
            }]);
            let error = validate_policy_capabilities(&policy_with_route(route))
                .expect_err("unsupported pattern must fail policy load");
            assert!(error.contains(constraint_type));
            assert!(error.contains("field safe"));
            assert!(error.contains("unsupported by the Rust runtime"));
        }
    }

    #[test]
    fn response_json_policy_admission_rejects_invalid_contracts() {
        let valid_constraint = response_json_constraint();
        let mut valid_route = generic_policy_route("none", json!(1024));
        valid_route["constraints"] = json!([valid_constraint.clone()]);
        validate_policy_capabilities(&policy_with_route(valid_route))
            .expect("valid responseJson policy must be admitted");

        let invalid_constraints = [
            (
                "wrong phase",
                json!({
                    "id":"bad","type":"responseJson","phase":"request",
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "unknown constraint field",
                json!({
                    "id":"bad","type":"responseJson","phase":"response","unknown":true,
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "empty operations",
                json!({
                    "id":"bad","type":"responseJson","phase":"response","operations":[],
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "duplicate operations",
                json!({
                    "id":"bad","type":"responseJson","phase":"response",
                    "operations":["widgets.read","widgets.read"],
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "malformed operation",
                json!({
                    "id":"bad","type":"responseJson","phase":"response",
                    "operations":["bad operation"],
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "empty items",
                json!({
                    "id":"bad","type":"responseJson","phase":"response","items":[],
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "duplicate items",
                json!({
                    "id":"bad","type":"responseJson","phase":"response","items":["data","data"],
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "malformed item path",
                json!({
                    "id":"bad","type":"responseJson","phase":"response","items":["data..items"],
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "wildcard item path",
                json!({
                    "id":"bad","type":"responseJson","phase":"response","items":["data.*.items"],
                    "fields":{"id":{"type":"string"}}
                }),
            ),
            (
                "empty fields",
                json!({"id":"bad","type":"responseJson","phase":"response","fields":{}}),
            ),
            (
                "malformed fields",
                json!({"id":"bad","type":"responseJson","phase":"response","fields":[]}),
            ),
            (
                "empty rule",
                json!({
                    "id":"bad","type":"responseJson","phase":"response","fields":{"id":{}}
                }),
            ),
            (
                "unknown rule",
                json!({
                    "id":"bad","type":"responseJson","phase":"response",
                    "fields":{"id":{"format":"uuid"}}
                }),
            ),
            (
                "malformed rule",
                json!({
                    "id":"bad","type":"responseJson","phase":"response",
                    "fields":{"id":{"required":"yes"}}
                }),
            ),
            (
                "pattern without input bound",
                json!({
                    "id":"bad","type":"responseJson","phase":"response",
                    "fields":{"id":{"pattern":"^item_[0-9]+$"}}
                }),
            ),
            (
                "pattern with oversized input bound",
                json!({
                    "id":"bad","type":"responseJson","phase":"response",
                    "fields":{"id":{"maxLength":4097,"pattern":"^item_[0-9]{1,4}$"}}
                }),
            ),
            (
                "pattern outside bounded runtime grammar",
                json!({
                    "id":"bad","type":"responseJson","phase":"response",
                    "fields":{"id":{"maxLength":64,"pattern":"^item_[0-9]+$"}}
                }),
            ),
            (
                "inverted range",
                json!({
                    "id":"bad","type":"responseJson","phase":"response",
                    "fields":{"score":{"min":10,"max":1}}
                }),
            ),
        ];
        for (label, constraint) in invalid_constraints {
            let mut route = generic_policy_route("none", json!(1024));
            route["constraints"] = json!([constraint]);
            assert!(
                validate_policy_capabilities(&policy_with_route(route)).is_err(),
                "{label} must fail policy admission"
            );
        }

        let mut streaming = generic_policy_route("none", json!(1024));
        streaming["adapter"]["config"]["response"]["mode"] = json!("jsonArrayStream");
        streaming["constraints"] = json!([valid_constraint]);
        let error = validate_policy_capabilities(&policy_with_route(streaming))
            .expect_err("responseJson cannot be used with streaming responses");
        assert!(error.contains("cannot stream responses with whole-body response constraints"));
    }

    #[test]
    fn query_numeric_bounds_reject_non_finite_values() {
        let constraint = json!({
            "id":"numeric",
            "type":"queryNumericBounds",
            "parameters":["limit"],
            "min":0,
            "max":10
        });
        for query in [
            "limit=NaN",
            "limit=Infinity",
            "limit=-Infinity",
            "limit=1e9999",
            "limit=5&limit=NaN",
        ] {
            let url = Url::parse(&format!("https://example.test/resource?{query}")).expect("URL");
            let denied = enforce_query_numeric_bounds(&constraint, &url)
                .expect_err("non-finite query value must fail closed");
            assert_eq!(denied["error"], "query_numeric_parameter_invalid");
            assert_eq!(denied["parameter"], "limit");
        }
        for query in ["limit=0", "limit=5.5", "limit=10", "limit=0&limit=10"] {
            let url = Url::parse(&format!("https://example.test/resource?{query}")).expect("URL");
            enforce_query_numeric_bounds(&constraint, &url).expect("finite in-range value");
        }
    }

    #[test]
    fn request_value_vectors_match_python_contract() {
        let vectors = [
            (
                "equals-allow",
                json!({"kind":"equals","value":"approved"}),
                "approved",
                true,
            ),
            (
                "equals-deny",
                json!({"kind":"equals","value":"approved"}),
                "other",
                false,
            ),
            (
                "enum-allow",
                json!({"kind":"enum","values":["open","closed"]}),
                "open",
                true,
            ),
            (
                "enum-deny",
                json!({"kind":"enum","values":["open","closed"]}),
                "all",
                false,
            ),
            (
                "pattern-allow",
                json!({"kind":"pattern","pattern":"^[A-Za-z0-9._-]{1,16}$","maxLength":16}),
                "repo-1",
                true,
            ),
            (
                "pattern-deny",
                json!({"kind":"pattern","pattern":"^[A-Za-z0-9._-]{1,16}$","maxLength":16}),
                "repo/1",
                false,
            ),
            (
                "length-byte-allow",
                json!({"kind":"stringLength","minLength":2,"maxLength":2}),
                "é",
                true,
            ),
            (
                "length-byte-deny",
                json!({"kind":"stringLength","maxLength":1}),
                "é",
                false,
            ),
            (
                "integer-allow",
                json!({"kind":"numeric","min":1,"max":50,"integer":true}),
                "42",
                true,
            ),
            (
                "integer-canonical-deny",
                json!({"kind":"numeric","min":1,"max":50,"integer":true}),
                "+42",
                false,
            ),
            (
                "integer-above-f64-precision-deny",
                json!({"kind":"numeric","max":9007199254740992_i64,"integer":true}),
                "9007199254740993",
                false,
            ),
            (
                "integer-i64-maximum-allow",
                json!({"kind":"numeric","min":i64::MAX,"integer":true}),
                "9223372036854775807",
                true,
            ),
            (
                "integer-outside-i64-deny",
                json!({"kind":"numeric","max":i64::MAX,"integer":true}),
                "9223372036854775808",
                false,
            ),
            (
                "number-allow",
                json!({"kind":"numeric","min":1.25,"max":2.5}),
                "1.5",
                true,
            ),
            (
                "number-whitespace-deny",
                json!({"kind":"numeric","min":1.25,"max":2.5}),
                " 1.5",
                false,
            ),
            (
                "number-finite-deny",
                json!({"kind":"numeric","min":0}),
                "NaN",
                false,
            ),
        ];
        for (label, predicate, value, expected_allowed) in vectors {
            let constraint = json!({
                "id":label,
                "type":"requestValue",
                "rules":[{
                    "source":"query",
                    "name":"scope",
                    "predicate":predicate,
                    "capture":"validatedScope",
                }],
            });
            let mut url = Url::parse("https://example.test/items").expect("URL");
            url.query_pairs_mut().append_pair("scope", value);
            let mut operation = json!({"operation":"vectors.read"});
            let result = enforce_request_value(
                &constraint,
                &BTreeMap::new(),
                &url,
                &BTreeMap::new(),
                &mut operation,
            );
            assert_eq!(result.is_ok(), expected_allowed, "{label}: {result:?}");
            assert_eq!(
                operation.get("validatedScope").and_then(Value::as_str) == Some(value),
                expected_allowed,
                "{label} capture"
            );
        }

        assert!(!request_value_predicate_matches(
            json!({"kind":"stringLength","minLength":1})
                .as_object()
                .expect("predicate"),
            &"x".repeat(4097),
        ));

        let constraint = json!({
            "id":"single-query-value",
            "type":"requestValue",
            "rules":[{
                "source":"query",
                "name":"scope",
                "predicate":{"kind":"equals","value":"approved"},
            }],
        });
        let url =
            Url::parse("https://example.test/items?scope=approved&scope=approved").expect("URL");
        let denied = enforce_request_value(
            &constraint,
            &BTreeMap::new(),
            &url,
            &BTreeMap::new(),
            &mut json!({"operation":"vectors.read"}),
        )
        .expect_err("duplicate query values must deny");
        assert_eq!(denied["error"], "request_value_ambiguous");

        let path_constraint = json!({
            "id":"path-and-header",
            "type":"requestValue",
            "rules":[
                {
                    "source":"pathParam",
                    "name":"owner",
                    "predicate":{"kind":"equals","value":"approved-owner"},
                    "capture":"owner",
                },
                {
                    "source":"header",
                    "name":"x-tenant-id",
                    "predicate":{"kind":"enum","values":["tenant-a"]},
                },
            ],
        });
        let mut operation = json!({"operation":"vectors.read"});
        enforce_request_value(
            &path_constraint,
            &BTreeMap::from([("x-tenant-id".to_string(), "tenant-a".to_string())]),
            &Url::parse("https://example.test/repos/approved-owner").expect("URL"),
            &BTreeMap::from([("owner".to_string(), "approved-owner".to_string())]),
            &mut operation,
        )
        .expect("single path and header values pass");
        assert_eq!(operation["owner"], "approved-owner");

        let collision_constraint = json!({
            "id":"reserved-capture",
            "type":"requestValue",
            "rules":[{
                "source":"pathParam",
                "name":"owner",
                "predicate":{"kind":"equals","value":"approved-owner"},
                "capture":"providerAccount",
            }],
        });
        let denied = enforce_request_value(
            &collision_constraint,
            &BTreeMap::new(),
            &Url::parse("https://example.test/repos/approved-owner").expect("URL"),
            &BTreeMap::from([("owner".to_string(), "approved-owner".to_string())]),
            &mut json!({"operation":"vectors.read","providerAccount":"trusted"}),
        )
        .expect_err("request value capture must not replace provider account identity");
        assert_eq!(denied["error"], "constraint_invalid_request_value");
    }

    #[test]
    fn request_value_policy_admission_is_closed_and_source_aware() {
        let mut route = generic_policy_route("none", json!(1024));
        route["match"]["paths"] = json!(["/repos/{owner}/{repo}"]);
        route["adapter"]["config"]["request"]["allowedHeaders"] = json!(["accept", "x-tenant-id"]);
        route["adapter"]["config"]["request"]["allowedQueryKeys"] = json!(["state"]);
        route["constraints"] = json!([{
            "id":"repository-scope",
            "type":"requestValue",
            "rules":[
                {
                    "source":"pathParam",
                    "name":"owner",
                    "predicate":{"kind":"equals","value":"approved-owner"},
                    "capture":"owner",
                },
                {
                    "source":"pathParam",
                    "name":"repo",
                    "predicate":{"kind":"pattern","pattern":"^[A-Za-z0-9._-]{1,64}$","maxLength":64},
                },
                {
                    "source":"query",
                    "name":"state",
                    "predicate":{"kind":"enum","values":["open","closed"]},
                },
                {
                    "source":"header",
                    "name":"x-tenant-id",
                    "predicate":{"kind":"stringLength","minLength":1,"maxLength":64},
                },
            ],
        }]);
        validate_policy_capabilities(&policy_with_route(route.clone()))
            .expect("bounded requestValue policy");

        let mutations = [
            ("unknown predicate field", json!({"unknown":true})),
            ("mixed predicate family", json!({"values":["mixed"]})),
        ];
        for (label, addition) in mutations {
            let mut invalid = route.clone();
            let predicate = invalid["constraints"][0]["rules"][0]["predicate"]
                .as_object_mut()
                .expect("predicate");
            predicate.extend(addition.as_object().expect("addition").clone());
            assert!(
                validate_policy_capabilities(&policy_with_route(invalid)).is_err(),
                "{label} must fail admission"
            );
        }

        let mut invalid_path = route.clone();
        invalid_path["constraints"][0]["rules"][0]["name"] = json!("missing");
        assert!(validate_policy_capabilities(&policy_with_route(invalid_path)).is_err());

        let mut invalid_query = route.clone();
        invalid_query["constraints"][0]["rules"][2]["name"] = json!("visibility");
        assert!(validate_policy_capabilities(&policy_with_route(invalid_query)).is_err());

        let mut invalid_header = route.clone();
        invalid_header["constraints"][0]["rules"][3]["name"] = json!("X-Tenant-Id");
        assert!(validate_policy_capabilities(&policy_with_route(invalid_header)).is_err());

        let mut reserved_capture = route.clone();
        reserved_capture["constraints"][0]["rules"][0]["capture"] =
            json!(PROVIDER_ACCOUNT_OPERATION_FIELD);
        assert!(validate_policy_capabilities(&policy_with_route(reserved_capture)).is_err());

        for invalid_bound in [json!(1.5), json!(9223372036854775808_u64)] {
            let mut invalid_integer = route.clone();
            invalid_integer["constraints"][0]["rules"][0]["predicate"] = json!({
                "kind":"numeric",
                "min":invalid_bound,
                "integer":true,
            });
            assert!(validate_policy_capabilities(&policy_with_route(invalid_integer)).is_err());
        }

        let mut too_many = route;
        let rule = too_many["constraints"][0]["rules"][0].clone();
        too_many["constraints"][0]["rules"] = json!(vec![rule; 17]);
        assert!(validate_policy_capabilities(&policy_with_route(too_many)).is_err());
    }

    #[test]
    fn client_proof_request_binding_is_canonical_and_sanitized() {
        let mut request = IncomingRequest {
            method: "GET".to_string(),
            target: "https://EXAMPLE.test.:443/resource?b=2&a=x&a=%7E".to_string(),
            headers: BTreeMap::from([
                (
                    "Authorization".to_string(),
                    "Bearer client-secret".to_string(),
                ),
                ("Connection".to_string(), "keep-alive".to_string()),
                ("Host".to_string(), "EXAMPLE.test:443".to_string()),
                (
                    "Proxy-Authorization".to_string(),
                    "Basic proxy-secret".to_string(),
                ),
                ("X-Serverware-Agent".to_string(), "agent:test".to_string()),
                (
                    "X-Serverware-Data-Plane-Token".to_string(),
                    "identity-secret".to_string(),
                ),
                (
                    "X-Serverware-Proof-Nonce".to_string(),
                    "proof-nonce".to_string(),
                ),
                ("X-Visible".to_string(), "visible".to_string()),
            ]),
            body: Vec::new(),
            client_ip: Some("127.0.0.1".to_string()),
        };
        let context = ResponseProofContext {
            client_nonce: "proof-nonce".to_string(),
            client_nonce_bytes: vec![7; 32],
            tls_exporter: "test-exporter".to_string(),
        };
        let canonical = serde_json::to_value(
            canonical_client_proof_request(&request).expect("canonical binding"),
        )
        .expect("serialize binding");
        assert_eq!(canonical["apiVersion"], "serverware.clientProofRequest/v1");
        assert_eq!(canonical["method"], "GET");
        assert_eq!(canonical["scheme"], "https");
        assert_eq!(canonical["authority"], "example.test");
        assert_eq!(canonical["path"], "/resource");
        assert_eq!(
            canonical["query"],
            json!([["a", "x"], ["a", "~"], ["b", "2"]])
        );
        assert_eq!(canonical["headers"], json!({"x-visible":"visible"}));
        assert_eq!(canonical["body_sha256"], sha256_prefixed(b""));
        let digest = client_proof_request_digest(&request, &context).expect("request digest");

        request.target = "https://example.test/resource?a=~&b=2&a=x".to_string();
        request.headers.insert(
            "X-Serverware-Proof-Nonce".to_string(),
            "different-nonce".to_string(),
        );
        let equivalent_context = ResponseProofContext {
            client_nonce: "different-nonce".to_string(),
            ..context.clone()
        };
        let equivalent_digest =
            client_proof_request_digest(&request, &equivalent_context).expect("equivalent digest");
        assert_eq!(digest, equivalent_digest);

        request
            .headers
            .insert("X-Visible".to_string(), "changed".to_string());
        let changed = client_proof_request_digest(&request, &equivalent_context)
            .expect("changed request digest");
        assert_ne!(digest, changed);

        request.method = "POST".to_string();
        assert!(canonical_client_proof_request(&request).is_err());
        request.method = "HEAD".to_string();
        assert!(canonical_client_proof_request(&request).is_err());
        request.method = "GET".to_string();
        request.body = b"not-empty".to_vec();
        assert!(canonical_client_proof_request(&request).is_err());
    }

    #[test]
    fn client_proof_request_digest_is_preserved_in_the_decision() {
        let snapshot = test_snapshot(1);
        let state = test_gate_state(Arc::clone(&snapshot));
        let request = IncomingRequest {
            method: "GET".to_string(),
            target: "https://example.test/resource".to_string(),
            headers: BTreeMap::from([(
                RESPONSE_PROOF_NONCE_HEADER.to_string(),
                "proof-nonce".to_string(),
            )]),
            body: Vec::new(),
            client_ip: Some("127.0.0.1".to_string()),
        };
        let context = ResponseProofContext {
            client_nonce: "proof-nonce".to_string(),
            client_nonce_bytes: vec![7; 32],
            tls_exporter: "test-exporter".to_string(),
        };
        let expected = client_proof_request_digest(&request, &context).expect("request digest");
        let decision = decide_internal(
            &state,
            &snapshot,
            DecisionRequest {
                client_ip: request.client_ip,
                method: request.method,
                url: request.target,
                headers: request.headers,
                body: String::new(),
                body_sha256: Some(sha256_prefixed(b"")),
                forwarded_body_length: Some(0),
                forwarded_body_utf8_valid: Some(true),
                credential_metadata: BTreeMap::new(),
                gmail_proofs: Vec::new(),
                client_request_digest: Some(expected.clone()),
            },
            Some("agent:test"),
        );
        assert_eq!(decision["allowed"], true);
        assert_eq!(decision["client_request_digest"], expected);
    }

    #[test]
    fn request_time_windows_are_strict_and_fail_closed() {
        let schedule = json!({
            "id":"weekday-hours",
            "type":"requestTimeWindow",
            "timezone":"UTC",
            "notBefore":"2026-01-01T00:00:00Z",
            "notAfter":"2027-01-01T00:00:00Z",
            "weekdays":["mon","tue","wed","thu","fri"],
            "dailyWindows":[{"start":"13:00","end":"15:00"}]
        });
        let within = parse_rfc3339_ms("2026-07-14T14:00:00Z").expect("valid timestamp");
        enforce_request_time_window_at_ms(&schedule, within).expect("Tuesday within UTC window");
        let end = parse_rfc3339_ms("2026-07-14T15:00:00Z").expect("valid timestamp");
        assert_eq!(
            enforce_request_time_window_at_ms(&schedule, end)
                .expect_err("daily end must be exclusive")["error"],
            "request_time_daily_window_denied"
        );
        let saturday = parse_rfc3339_ms("2026-07-18T14:00:00Z").expect("valid timestamp");
        assert_eq!(
            enforce_request_time_window_at_ms(&schedule, saturday)
                .expect_err("weekend must be denied")["error"],
            "request_time_weekday_denied"
        );

        let mut route = generic_policy_route("none", json!(1024));
        route["constraints"] = json!([schedule]);
        validate_policy_capabilities(&policy_with_route(route.clone()))
            .expect("valid request schedule");
        route["constraints"][0]["dailyWindows"] = json!([
            {"start":"09:00","end":"12:00"},
            {"start":"11:00","end":"13:00"}
        ]);
        assert!(validate_policy_capabilities(&policy_with_route(route))
            .expect_err("overlapping windows must fail policy load")
            .contains("must not overlap"));

        let date_only = HashSet::from(["date"]);
        assert!(parse_datetime_ms(&json!("2026-07-14"), &date_only).is_some());
        assert!(parse_datetime_ms(&json!("2026-02-30"), &date_only).is_none());
        assert!(parse_datetime_ms(&json!("2026-07-14T00:00:00Z"), &date_only).is_none());
        let rfc3339 = HashSet::from(["rfc3339"]);
        assert_eq!(
            parse_datetime_ms(&json!("2026-07-14T10:00:00-04:00"), &rfc3339),
            Some(within)
        );
    }

    #[test]
    fn route_matching_uses_python_per_segment_specificity() {
        let mut snapshot = (*test_snapshot(1)).clone();
        snapshot.routes = vec![
            route_with_path("glob", "/items/**"),
            route_with_path("wildcard", "/items/*/detail"),
            route_with_path("variable", "/items/{item}/detail"),
            route_with_path("literal", "/items/special/*"),
        ];
        let url = Url::parse("https://example.test/items/special/detail").expect("URL");
        assert_eq!(
            snapshot
                .match_route("agent:test", "GET", &url)
                .expect("specific route")
                .route
                .id,
            "literal"
        );

        snapshot.routes.remove(3);
        assert_eq!(
            snapshot
                .match_route("agent:test", "GET", &url)
                .expect("variable route")
                .route
                .id,
            "variable"
        );

        snapshot.routes.remove(2);
        assert_eq!(
            snapshot
                .match_route("agent:test", "GET", &url)
                .expect("wildcard route")
                .route
                .id,
            "wildcard"
        );
    }

