    #[test]
    fn audit_post_accepts_exact_signed_acknowledgement_with_fresh_nonces() {
        let response_signing_key = SigningKey::from_bytes(&[34u8; 32]);
        let snapshot = test_snapshot_with_control_plane_response_key(1, &response_signing_key);
        let server_snapshot = Arc::clone(&snapshot);
        let listener = TcpListener::bind("127.0.0.1:0").expect("audit listener");
        let address = listener.local_addr().expect("audit listener address");
        let server = thread::spawn(move || {
            let mut requests = Vec::new();
            for _ in 0..2 {
                let (mut stream, request) = read_audit_test_request(&listener);
                let batch_digest = sha256_prefixed(&request.body);
                let response = signed_audit_test_acknowledgement(
                    &response_signing_key,
                    &server_snapshot,
                    &request,
                    1,
                    &batch_digest,
                );
                stream
                    .write_all(&response)
                    .expect("write signed audit acknowledgement");
                requests.push(request);
            }
            requests
        });
        let mut state = test_gate_state(snapshot);
        state.server_instance_id = Some("test-instance".to_string());
        state.audit_url = Some(format!("http://{address}/api/data-plane/audit"));
        state.audit_token = Some("audit-token".to_string());
        let batch = [test_audit_event(
            1,
            "data_plane.test",
            json!({"marker":"exact"}),
            false,
        )];

        post_audit_batch(&state, &batch).expect("first signed audit acknowledgement");
        post_audit_batch(&state, &batch).expect("second signed audit acknowledgement");
        let requests = server.join().expect("audit server");
        assert_eq!(requests[0].body, requests[1].body);
        let expected_body = serde_json::to_vec(&json!({
            "events":[{
                "event":{"marker":"exact"},
                "eventId":test_audit_event_id(1),
                "eventType":"data_plane.test",
            }],
        }))
        .expect("serialize expected audit body");
        assert_eq!(requests[0].body, expected_body);
        let first_nonce = requests[0]
            .headers
            .get("x-serverware-response-nonce")
            .expect("first response nonce");
        let second_nonce = requests[1]
            .headers
            .get("x-serverware-response-nonce")
            .expect("second response nonce");
        assert_ne!(first_nonce, second_nonce, "each POST needs a fresh nonce");
    }

    #[test]
    fn credential_release_requires_durable_audit_acknowledgement() {
        let response_signing_key = SigningKey::from_bytes(&[35u8; 32]);
        let snapshot = test_snapshot_with_control_plane_response_key(1, &response_signing_key);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.server_instance_id = Some("test-instance".to_string());
        let binding = CredentialLeaseReleaseBinding {
            scope: CredentialLeaseScope::new("agent:test", "route:test", "credential:test"),
            version: 7,
            secret_fingerprint: credential_secret_fingerprint("secret"),
            expires_at_monotonic: Instant::now() + Duration::from_secs(5),
        };
        let decision = json!({
            "principal_id":"agent:test",
            "route_id":"route:test",
            "policy_hash":"sha256:policy",
            "request_digest":"sha256:request",
            "operation_digest":"sha256:operation",
            "enrollment_session_id":"A_-0123456789abcdefghijk",
        });
        let url = Url::parse("https://example.test/resource").expect("URL");
        assert!(!record_required_credential_release_start(
            &state, &decision, "GET", &url, &binding,
        ));

        let listener = TcpListener::bind("127.0.0.1:0").expect("audit test listener");
        let address = listener.local_addr().expect("audit test address");
        let server_snapshot = Arc::clone(&snapshot);
        let server = thread::spawn(move || {
            let (mut stream, request) = read_audit_test_request(&listener);
            let batch_digest = sha256_prefixed(&request.body);
            let response = signed_audit_test_acknowledgement(
                &response_signing_key,
                &server_snapshot,
                &request,
                1,
                &batch_digest,
            );
            stream
                .write_all(&response)
                .expect("write audit acknowledgement");
            request
        });
        state.audit_url = Some(format!("http://{address}/api/data-plane/audit"));
        state.audit_token = Some("token".to_string());
        state.audit_queue_max = 1;
        assert!(record_required_credential_release_start(
            &state, &decision, "GET", &url, &binding,
        ));
        let captured = server.join().expect("audit test server");
        let captured = strict_json_value_from_slice(&captured.body).expect("audit batch JSON");
        assert_eq!(
            captured["events"][0]["eventType"],
            "data_plane.credential.release_started"
        );
        assert!(is_sha256_digest(
            captured["events"][0]["eventId"]
                .as_str()
                .expect("credential release audit event ID")
        ));
        assert_eq!(
            captured["events"][0]["event"]["credential_ref"],
            "credential:test"
        );
        assert_eq!(
            captured["events"][0]["event"]["enrollment_session_id"],
            "A_-0123456789abcdefghijk"
        );
        assert!(state.audit_queue.lock().expect("audit queue").is_empty());
        assert_eq!(state.audit_sent.load(Ordering::Relaxed), 1);
        assert!(!record_required_credential_release_start(
            &state, &decision, "GET", &url, &binding,
        ));
        assert_eq!(state.audit_required_failed.load(Ordering::Relaxed), 2);
    }

    #[test]
    fn delayed_audit_acknowledgement_requires_lease_revalidation() {
        let response_signing_key = SigningKey::from_bytes(&[36u8; 32]);
        let snapshot = test_snapshot_with_control_plane_response_key(1, &response_signing_key);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.server_instance_id = Some("test-instance".to_string());
        let scope = CredentialLeaseScope::new("agent:test", "route:test", "credential:test");
        let expiry = Instant::now() + Duration::from_millis(40);
        state.credential_leases.lock().expect("lease cache").insert(
            scope.clone(),
            SecretLease {
                scope: scope.clone(),
                version: 7,
                secret: Zeroizing::new("secret".to_string()),
                metadata: BTreeMap::new(),
                policy_hash: snapshot.hash.clone(),
                expires_at_epoch_ms: now_epoch_ms() + 40,
                expires_at_monotonic: expiry,
            },
        );
        let binding = CredentialLeaseReleaseBinding {
            scope,
            version: 7,
            secret_fingerprint: credential_secret_fingerprint("secret"),
            expires_at_monotonic: expiry,
        };
        assert!(credential_lease_still_releasable(
            &state, &snapshot, &binding
        ));

        let listener = TcpListener::bind("127.0.0.1:0").expect("audit test listener");
        let address = listener.local_addr().expect("audit test address");
        let server_snapshot = Arc::clone(&snapshot);
        let server = thread::spawn(move || {
            let (mut stream, request) = read_audit_test_request(&listener);
            thread::sleep(Duration::from_millis(80));
            let batch_digest = sha256_prefixed(&request.body);
            let response = signed_audit_test_acknowledgement(
                &response_signing_key,
                &server_snapshot,
                &request,
                1,
                &batch_digest,
            );
            stream
                .write_all(&response)
                .expect("write audit acknowledgement");
        });
        state.audit_url = Some(format!("http://{address}/api/data-plane/audit"));
        state.audit_token = Some("token".to_string());
        let decision = json!({
            "principal_id":"agent:test",
            "route_id":"route:test",
            "policy_hash":snapshot.hash,
            "request_digest":"sha256:request",
            "operation_digest":"sha256:operation",
        });
        let url = Url::parse("https://example.test/resource").expect("URL");
        assert!(record_required_credential_release_start(
            &state, &decision, "GET", &url, &binding,
        ));
        server.join().expect("audit test server");
        assert!(!credential_lease_still_releasable(
            &state, &snapshot, &binding
        ));
    }

    fn cache_test_credential_lease_for_send(
        state: &GateState,
        snapshot: &Arc<Snapshot>,
        lifetime: Duration,
    ) -> CredentialLeaseReleaseBinding {
        let scope = CredentialLeaseScope::new("agent:test", "route:test", "credential:test");
        let lease = SecretLease {
            scope: scope.clone(),
            version: 7,
            secret: Zeroizing::new("upstream-secret".to_string()),
            metadata: BTreeMap::new(),
            policy_hash: snapshot.hash.clone(),
            expires_at_epoch_ms: now_epoch_ms() + lifetime.as_millis(),
            expires_at_monotonic: Instant::now() + lifetime,
        };
        let binding = credential_lease_release_binding(&lease);
        cache_scoped_credential_lease(state, snapshot, &scope, lease)
            .expect("cache test credential lease generation");
        binding
    }

    #[test]
    fn buffered_upstream_send_rejects_lease_expiry_during_dispatch() {
        let snapshot = test_snapshot(1);
        let state = test_gate_state(Arc::clone(&snapshot));
        let binding =
            cache_test_credential_lease_for_send(&state, &snapshot, Duration::from_millis(40));
        let listener = TcpListener::bind("127.0.0.1:0").expect("buffered upstream listener");
        listener
            .set_nonblocking(true)
            .expect("nonblocking buffered upstream listener");
        let address = listener.local_addr().expect("buffered upstream address");
        let builder = state
            .one_shot_upstream_client
            .post(format!("http://{address}/resource"))
            .body(br#"{"safe":true}"#.to_vec());

        thread::sleep(Duration::from_millis(80));
        let error = send_upstream_request_with_current_lease(
            &state,
            &snapshot,
            Some(&binding),
            builder,
            false,
        )
        .expect_err("lease expiring during dispatch must block buffered send");
        assert!(matches!(
            error,
            UpstreamSendError::CredentialAuthority("credential_lease_expired_before_upstream_send")
        ));
        assert_eq!(
            listener
                .accept()
                .expect_err("expired buffered lease must not contact upstream")
                .kind(),
            io::ErrorKind::WouldBlock
        );
    }

    #[test]
    fn buffered_proof_rechecks_custody_health_at_the_upstream_send_boundary() {
        let snapshot = test_snapshot(1);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.response_proof_signer =
            test_custody_response_proof_signer(sha256_prefixed(b"control-plane-response-spki"));
        let ResponseProofSigner::Custody(signer) = &state.response_proof_signer else {
            panic!("custody signer");
        };
        let operation = signer.health.begin_probe();
        signer
            .health
            .record_probe_failure(operation, "custody became unavailable");

        let listener = TcpListener::bind("127.0.0.1:0").expect("proof upstream listener");
        listener
            .set_nonblocking(true)
            .expect("nonblocking proof upstream listener");
        let address = listener.local_addr().expect("proof upstream address");
        let builder = state
            .one_shot_upstream_client
            .get(format!("http://{address}/resource"));
        let error =
            send_upstream_request_with_current_lease(&state, &snapshot, None, builder, true)
                .expect_err("unhealthy custody must block the final upstream send");
        assert!(matches!(
            error,
            UpstreamSendError::CredentialAuthority("response_proof_unavailable")
        ));
        assert_eq!(
            listener
                .accept()
                .expect_err("unhealthy custody must not contact upstream")
                .kind(),
            io::ErrorKind::WouldBlock
        );
    }

    #[test]
    fn buffered_proof_revalidates_lease_after_waiting_for_dispatch_permit() {
        let snapshot = test_snapshot(1);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.response_proof_signer =
            test_custody_response_proof_signer(sha256_prefixed(b"control-plane-response-spki"));
        let state = Arc::new(state);
        let binding =
            cache_test_credential_lease_for_send(&state, &snapshot, Duration::from_secs(5));
        let ResponseProofSigner::Custody(signer) = &state.response_proof_signer else {
            panic!("custody signer");
        };
        let blocking_permit = signer.health.acquire_dispatch_permit();
        let transition_health = Arc::clone(&signer.health);
        let transition = thread::spawn(move || {
            let operation = transition_health.begin_probe();
            transition_health.record_probe_success(operation);
        });
        for _ in 0..100 {
            if signer
                .health
                .dispatch_coordination
                .lock()
                .expect("custody dispatch coordination")
                .waiting_transitions
                != 0
            {
                break;
            }
            thread::sleep(Duration::from_millis(1));
        }
        assert_ne!(
            signer
                .health
                .dispatch_coordination
                .lock()
                .expect("custody dispatch coordination")
                .waiting_transitions,
            0
        );

        let listener = TcpListener::bind("127.0.0.1:0").expect("proof upstream listener");
        listener
            .set_nonblocking(true)
            .expect("nonblocking proof upstream listener");
        let address = listener.local_addr().expect("proof upstream address");
        let worker_state = Arc::clone(&state);
        let worker_snapshot = Arc::clone(&snapshot);
        let worker_binding = binding.clone();
        let send = thread::spawn(move || {
            let builder = worker_state
                .one_shot_upstream_client
                .get(format!("http://{address}/resource"));
            send_upstream_request_with_current_lease(
                &worker_state,
                &worker_snapshot,
                Some(&worker_binding),
                builder,
                true,
            )
        });
        for _ in 0..100 {
            if signer
                .health
                .dispatch_coordination
                .lock()
                .expect("custody dispatch coordination")
                .waiting_dispatches
                == 1
            {
                break;
            }
            thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            signer
                .health
                .dispatch_coordination
                .lock()
                .expect("custody dispatch coordination")
                .waiting_dispatches,
            1,
            "the sender must reach the blocked dispatch-permit acquisition"
        );
        state
            .credential_leases
            .lock()
            .expect("credential lease cache")
            .remove(&binding.scope);
        drop(blocking_permit);
        transition.join().expect("custody health transition");
        let error = send
            .join()
            .expect("buffered proof send worker")
            .expect_err("revoked lease must be rechecked after dispatch-permit wait");
        assert!(matches!(
            error,
            UpstreamSendError::CredentialAuthority("credential_lease_changed_before_upstream_send")
        ));
        assert_eq!(
            listener
                .accept()
                .expect_err("revoked lease must not contact upstream")
                .kind(),
            io::ErrorKind::WouldBlock
        );
    }

