    #[test]
    fn local_rate_precheck_is_non_mutating_and_consume_sweeps_expired_entries() {
        let snapshot = test_snapshot(1);
        let state = test_gate_state(Arc::clone(&snapshot));
        let route = &snapshot.routes[0];
        let constraint = json!({
            "id":"local-rate",
            "type":"rateLimit",
            "max":1,
            "windowSeconds":60,
            "store":"local"
        });
        let operation = json!({"operation":"read"});
        enforce_rate_limit(
            &state,
            &constraint,
            route,
            "agent:test",
            None,
            0,
            &snapshot.hash,
            &operation,
            false,
            false,
        )
        .expect("precheck");
        assert!(state
            .constraint_rate_counters
            .lock()
            .expect("rate counters")
            .is_empty());

        let key = rate_limit_key(&constraint, route, "agent:test", None, 0, &operation);
        state
            .constraint_rate_counters
            .lock()
            .expect("rate counters")
            .insert(
                key,
                ConstraintRateCounter {
                    expires_at_ms: now_epoch_ms().saturating_sub(1),
                    count: 1,
                },
            );
        enforce_rate_limit(
            &state,
            &constraint,
            route,
            "agent:test",
            None,
            0,
            &snapshot.hash,
            &operation,
            false,
            false,
        )
        .expect("read-only precheck with expired entry");
        assert_eq!(
            state
                .constraint_rate_counters
                .lock()
                .expect("rate counters")
                .len(),
            1
        );
        enforce_rate_limit(
            &state,
            &constraint,
            route,
            "agent:test",
            None,
            0,
            &snapshot.hash,
            &operation,
            true,
            false,
        )
        .expect("consuming check after expiry");
        assert_eq!(
            state
                .constraint_rate_counters
                .lock()
                .expect("rate counters")
                .values()
                .next()
                .map(|counter| counter.count),
            Some(1)
        );
    }

